  playExerciseAudio(ex.audio);
  setExerciseState(EX_STATE.INICIAL, 'renderExercise'); // Motor de estados, Fase 1 (2026-08-24) — ejercicio recién cargado, universal para todos los kinds (incluye concept/slides/exp, que retornan antes más abajo)
  // Activar modo guided si el ejercicio lo declara
  if(ex.guided && ex.guidedMessages && ex.guidedMessages.length){
    state.guidedActive=true;
    state._guidedTimer=setTimeout(()=>{ state._guidedTimer=null; guidedMsg('start'); }, 200);
  }
  // MATH_PLUGIN fase 6 (plan post-lote, 2026-07-22): reset por-kind en vez
  // de resetear las 22 banderas de los 12 kinds SIEMPRE, sin importar cuál
  // es el ejercicio actual. Verificado con grep (MAPA_DEPENDENCIAS_MATH_
  // PLUGIN_v1.md §5): cada bandera se lee únicamente dentro del renderer y
