function renderExplicacionMultipaso(container, c, onDone){
  const steps = c.steps || [];
  let idx = 0;
  function showStep(){
    container.innerHTML = '';
    const step = steps[idx];
    const isLast = idx === steps.length - 1;
    renderExplicacionCorta(container, step);
    if (c.narrate) speakText(explicacionNarrateText(step));
    if (steps.length > 1) {
      // Mismo lenguaje visual que renderConcept()/.concept-dots (Nivel 4 del
      // Motor) — el patrón multipaso ya existía, se reusan las clases, no se
      // reescribe la lógica (que está atada a handleConfirm()/kind:'concept',
      // un contexto distinto al de un sheet).
      const nav=document.createElement('div'); nav.className='concept-nav';
      const dots=document.createElement('div'); dots.className='concept-dots';
      steps.forEach((_, i)=>{ const d=document.createElement('div'); d.className='concept-dot'+(i===idx?' active':''); dots.appendChild(d); });
      nav.appendChild(dots); container.appendChild(nav);
    }
    const btn=document.createElement('button'); btn.type='button'; btn.className='pds-btn-depth';
    btn.textContent = isLast ? 'Lo entiendo' : 'Siguiente →';
    btn.onclick = () => { if (isLast) { if (onDone) onDone(); } else { idx++; showStep(); } };
    container.appendChild(btn);
  }
  showStep();
}
function appendExplicacionDone(container, onDone, label){
  const btn=document.createElement('button'); btn.type='button'; btn.className='pds-btn-depth'; btn.style.marginTop='4px'; btn.textContent=label||'Lo entiendo';
  btn.onclick = () => { if (onDone) onDone(); };
  container.appendChild(btn);
}

// #help-panel es compartido (Fase 3 lo abrió primero para el menú del
// tutor; Fase 4/10, 2026-08-24, suma "¿Por qué?" al mismo panel en vez de
// crear un sexto sheet). Regla explícita del Director: "quien abre, define
// el contenido completo de #help-content" — cada opener reescribe TODO
// (título/subtítulo + contenido), nunca deja restos del otro. state.
// _helpPanelSource ('tutor-menu'|'why-sheet'|'error-sheet') es lo único que
// closeHelp() necesita para saber qué transición de estado le corresponde
// al cerrar — abrir el menú del tutor no tiene semántica de estado propia
// (Fase 3, sin cambios), abrir "¿Por qué?" sí (EXPLICACION↔origen dinámico,
// Fases 4/6). Fase 7/10 (2026-08-24): las 3 responsabilidades ahora se
// apoyan en BottomSheet para el contenedor — el flag de origen sigue
// siendo lo que las distingue, BottomSheet no sabe ni le importa cuál es.
// Tutor progresivo (encargo suelto, 2026-08-25, revisa Fases 3 y 7): Spike
// deja de ser un selector (menú de 2-3 opciones simultáneas, elegir cuál
// mirar) y pasa a asistencia progresiva — una capa por vez, dentro del
// sheet, sin acumular en el cuerpo del ejercicio (antes renderScaffoldLayer()
// hacía zone.appendChild(card) en #scaffold-zone; las 3 capas quedaban
// visibles juntas si el alumno las pedía todas — el hallazgo real de la
// auditoría de tutor/Brilliant, A2-A6). buildHelpLayers()/state.helpLayers/
// state.helpLevel NO se tocan — solo cambia cómo se presenta.
//
// advance=false (tap simple en Spike): muestra la capa que corresponde al
// state.helpLevel ACTUAL sin avanzar — re-tocar el tutor repite la misma
// capa (re-lee), nunca avanza sola. advance=true (botón explícito "¿Necesitás
// más ayuda?" DENTRO del sheet, o el auto-trigger de handleConfirm() al
// errar — ver esa función): consume la capa actual y pasa a la siguiente.
// Al agotar las 3, se muestra la última + un bloque de texto fijo
// "Conversar — próximamente" (placeholder de la Fase 9, sin botón activo).
//
// renderScaffoldLayer()/#scaffold-zone quedan sin llamador tras este cambio
// — no se borraron (no era parte de este encargo, "reusar, no reconstruir"),
// documentado acá para quien retome ese código muerto en una pasada aparte.
// Pieza 1 (2026-08-26): tocar el tutor con el sheet YA abierto lo cierra
// (toggle) — antes, tocar Spike de nuevo mientras el sheet estaba arriba
// simplemente re-mostraba la misma capa (openHelpMenu() sin avanzar), un
// gesto sin efecto visible aparente. La ✕ del header queda como
// alternativa secundaria de cierre, sin cambios.
function toggleTutorHelp(){
  if (document.getElementById('help-overlay').classList.contains('open')) { closeHelp(); return; }
  openHelpMenu();
}
// MICROENSEÑANZA — transcripción de la voz en off (§6 + corrección explícita
// del Director, 2026-09-06: "lo que se dice aparecería cuando tocás al
// tutor"). El texto NO se inventa ni se duplica: es el MISMO `ex.vozEntrada`
// que el Pipeline le manda a Polly para sintetizar `ex.audio`, así que la
// transcripción y la locución no pueden divergir nunca — son el mismo dato.
// Ese campo ya llegaba al artefacto pero el Motor no lo leía en ningún lado.
// Limpia el SSML: vozEntrada trae etiquetas (<lang xml:lang="en-US">has
// got</lang>) para que Polly pronuncie el inglés dentro del español; sin esta
// limpieza el alumno leería las etiquetas.
// Extraído de vozEntradaTexto() (Plan v2 §7/M6, 2026-09-07) para reusar la
// MISMA limpieza de SSML con screen.voz (Concepto, por pantalla) — el
// transcript nunca se autora aparte, siempre se deriva de este mismo texto.
// Refactor puro: vozEntradaTexto(ex) hace exactamente lo mismo que antes.
function ssmlToTexto(ssml) {
  if (!ssml) return '';
  return ssml
    .replace(/<[^>]*>/g, '')        // fuera las etiquetas SSML
    .replace(/\s+/g, ' ')           // espacios colapsados
    .replace(/\s+([.,;:!?…])/g, '$1') // sin espacio antes de puntuación (queda al sacar una etiqueta pegada al punto)
    .trim();
}
function vozEntradaTexto(ex) {
  if (!ex || !ex.vozEntrada) return '';
  return ssmlToTexto(ex.vozEntrada);
}
// Corrección transversal (2026-09-15, BUG 1 — "Cierre transversal de
// experiencia"): un `concept` con `screens[]` no tiene `ex.vozEntrada`
// (exclusivo de ejercicios evaluables) — su voz vive por pantalla,
// `ex.screens[i].voz`/`.audio`. Antes de este fix, esa voz nunca llegaba al
// Tutor Sheet (`vozEntradaTexto()`/`prependTranscripcion()` solo miraban
// `ex.vozEntrada`) — por eso `renderConceptScreens()` la pintaba aparte,
// permanente, fuera del sheet (ver comentario histórico ahí). Esta función
// unifica el origen: exercise-level para cualquier `kind` evaluable,
// screen-level para `concept` — el resto del mecanismo (sheet, label
// "Lo que te dije"/"Explicación", botón de replay) no cambia una línea.
function currentVozAudioSource(ex) {
  if (!ex) return null;
  if (ex.kind === 'concept' && Array.isArray(ex.screens)) {
    const area = document.getElementById('exercise-input-area');
    const idx = (area && typeof area._conceptPage === 'number') ? area._conceptPage : 0;
    const screen = ex.screens[idx];
    if (screen && screen.voz) return { voz: screen.voz, audio: screen.audio || null };
    return null;
  }
  if (ex.vozEntrada) return { voz: ex.vozEntrada, audio: ex.audio || null };
  return null;
}
// Se antepone al contenido del Tutor, no lo reemplaza: la escalera de ayuda
// sigue abajo, intacta. Deliberadamente breve (§6: "no convertir esto en una
// pantalla extensa de texto") — es una segunda vía de acceso al MISMO
// contenido pedagógico, no una lección escrita.
function prependTranscripcion(content, ex) {
  const src = currentVozAudioSource(ex);
  if (!src) return;
  // No regalar el audio (2026-10-04): en un ejercicio de escucha con texto en inglés, la transcripción es la respuesta; recién después de responder.
  if (ex && ex.kind !== 'concept' && ex.vozEntrada && !state.answered && (ex.kind === 'listen' || ex.answer !== undefined) && !pdpTextoEsEspanol(ssmlToTexto(ex.vozEntrada))) return;
  const txt = ssmlToTexto(src.voz);
  if (!txt) return;
  const box = document.createElement('div');
  box.className = 'tutor-transcript';
  const lbl = document.createElement('div');
  lbl.className = 'tutor-transcript-label';
  lbl.textContent = src.audio ? 'Lo que te dije' : 'Explicación';
  const p = document.createElement('div');
  p.className = 'tutor-transcript-text';
  p.textContent = txt;
  box.appendChild(lbl); box.appendChild(p);
  // Replay (Plan v2 §7/§9, ya existente para concept — reubicado acá tal
  // cual, mismo criterio: reusa el audio ya embebido, no sintetiza nada).
  if (src.audio) {
    const replayBtn = document.createElement('button'); replayBtn.type = 'button'; replayBtn.className = 'demo-replay';
    replayBtn.textContent = '▶ Escuchar de nuevo';
    replayBtn.onclick = () => { if (!audioEsReproducible(src.audio) && ex && ex.kind !== 'concept') { hablarVozEntrada({ vozEntrada: src.voz }); return; } playExerciseAudio(src.audio); }; // respaldo con la voz del dispositivo (2026-10-04)
    box.appendChild(replayBtn);
  }
  content.insertBefore(box, content.firstChild);
}
function openHelpMenu(advance){
  if (isEvalModule(state.currentModule)) return; // defensivo — el ícono ya está oculto en evaluación (updateHelpUI()), esto no debería ser alcanzable
  // Re-especificación Fase 7, Parte 2 (2026-08-25), invariante 4: si el
  // autoplay del dispositivo bloqueó ex.audio al entrar (política real de
  // gesto de usuario, no verificable en el pane), el alumno lo repite
  // tocando el tutor — mismo gesto del Tutor progresivo (tap simple,
  // advance falsy), ADEMÁS de mostrar la capa de ayuda actual, no en su
  // lugar. advance=true (avanzar de capa) NO re-dispara — evita que cada
  // "¿Necesitás más ayuda?" reinicie el audio de entrada sin sentido.
  // A2 — corrección de dispositivo real (2026-08-25): el re-disparo era
  // incondicional (gap del encargo original, no error de implementación) —
  // sonaba de nuevo aunque el autoplay de entrada ya hubiera sonado bien.
  // Ahora solo repite si state._exerciseAudioAutoplayOk !== true (bloqueado
  // o todavía sin resolver) — si ya sonó, tocar Spike solo muestra la capa.
  if (!advance) {
    const exs = getActiveExercises(state.currentModule), ex = exs[state.currentExerciseIndex];
    if (ex && ex.audio && state._exerciseAudioAutoplayOk !== true) playExerciseAudio(ex.audio);
    // BUG 1 (2026-09-15): mismo criterio para `concept` — su audio autoplay
    // real es `screens[i].audio` (ver showScreen()), no `ex.audio`. Reusa
    // currentVozAudioSource() en vez de leer `ex.screens` de nuevo acá.
    else if (ex && ex.kind === 'concept') {
      const src = currentVozAudioSource(ex);
      if (src && src.audio && state._exerciseAudioAutoplayOk !== true) playExerciseAudio(src.audio);
    }
    // Especificación Bottom Sheets + Tutor (2026-09-05, corrección
    // fundamental): si hay un Sheet de resultado (error/correcto/revelado)
    // visible, el Tutor lo REEMPLAZA, no se apila encima — #confirm-btn ya
    // tiene el texto/color/onclick correctos (los puso setPrimaryCTA()),
    // solo se compacta y flota (enterCompactCTA(), mismo nodo, nunca se
    // clona). closeHelp() lo restaura al cerrar. Si no hay ningún Sheet
    // visible (ayuda proactiva antes de responder, vía el tutor-strip), no
    // hay nada que ocultar ni compactar — comportamiento sin cambios.
    const fzOrigin = document.getElementById('feedback-zone');
    if (fzOrigin.classList.contains('visible')) {
      fzOrigin.classList.add('tutor-open');
      enterCompactCTA();
    }
  }
  const content=document.getElementById('help-content');
  const _exActual = getActiveExercises(state.currentModule)[state.currentExerciseIndex];
  const hasHelp = state.helpLayers && state.helpLayers.length>0;
  if (!hasHelp) {
    // Estado B: el tutor no tiene ayuda pedagógica para ESTE ejercicio —
    // no es lo mismo que "no hay tutor conversacional" (C, abajo). Sin
    // cambios respecto de antes.
    // 2026-09-06: pero si hubo voz en off, "no hay ayuda cargada" ya no es
    // toda la verdad — la explicación que el alumno escuchó SÍ existe y se
    // muestra arriba (ver prependTranscripcion()).
    let html = '<p class="help-menu-empty">Todavía no hay ayuda pedagógica cargada para este ejercicio.</p>';
    if (!hasTutorIA()) html += '<p class="help-menu-ia-note">💬 Conversar con el tutor — próximamente.</p>';
    // BUG 1 (2026-09-15): antes solo miraba vozEntradaTexto() (ex-level) —
    // un concept con voz por screen mostraba igual el mensaje "todavía no
    // hay ayuda", aunque prependTranscripcion() de abajo SÍ iba a pintar el
    // transcript. currentVozAudioSource() ya cubre ambos orígenes.
    content.innerHTML = currentVozAudioSource(_exActual) ? '' : html;
    prependTranscripcion(content, _exActual);
    BottomSheet.open('tutor-menu', '', 'normal'); // Pieza 1 (2026-08-26): sin subtítulo — ver comentario en BottomSheet.open()
    riseTutor(); // Pieza 1: el ascenso ya no es automático de open() — quien abre lo pide
    return;
  }
  state.usedHintThisEx = true;
  if (advance && state.helpLevel < state.helpLayers.length) state.helpLevel++;
  const exhausted = state.helpLevel >= state.helpLayers.length;
  const idx = exhausted ? state.helpLayers.length - 1 : state.helpLevel;
  const layer = state.helpLayers[idx];
  if (state.guidedActive && layer.kind==='hint' && !state._helpGuidedHintFired) {
    state._helpGuidedHintFired = true;
    guidedMsg('hint');
  }
  let html = renderHelpLayerHtml(layer, idx+1, state.helpLayers.length);
  if (exhausted) html += '<p class="help-menu-ia-note" style="margin-top:12px;">💬 Conversar — próximamente</p>';
  content.innerHTML = html;
  prependTranscripcion(content, _exActual); // la transcripción va ARRIBA de la escalera, no la reemplaza
  // Pieza 1 (2026-08-26): "¿Necesitás más ayuda?" pasa del cuerpo (botón
  // suelto adentro de #help-content) al botón de acción del header del
  // sheet. CORRECCIÓN (2026-08-26, hallazgo real del Director): "Revelar"
  // NO — cuando exhausted, #reveal-btn del footer ya está visible por su
  // propio gate (updateHelpUI(), misma condición hasHelp+exhausted, footer
  // accesible con el sheet abierto — invariante ya verificado en Pieza 1),
  // así que agregarle un 2do "Revelar" acá era pura duplicación. Sin
  // acción (4to parámetro ausente) cuando exhausted: BottomSheet.open() ya
  // sabe degradar a la ✕ de siempre sin acción (mismo camino que el
  // branch !hasHelp, arriba). doRevealFromHelp() queda sin llamador desde
  // acá — no se borra, "no reconstruir" (sigue siendo la función correcta
  // si el footer alguna vez deja de ser la vía).
  // CTA CONTEXTUAL ÚNICO DEL TUTOR (decisión del Director, 2026-09-06): el
  // botón de ayuda no desaparece al agotarse la escalera — CAMBIA DE ESTADO.
  //   PISTA 1/3 → PISTA 2/3 → PISTA 3/3 → Revelar
  // Es el mismo botón (#help-panel-action-btn) transformándose, no un segundo
  // botón. Antes, al agotarse, este parámetro pasaba `undefined` (el botón se
  // ocultaba) y "Revelar" vivía suelto en el footer — dos controles distintos
  // para dos momentos de la misma progresión, y encima uno de ellos anclado a
  // una franja que impedía que el Sheet fuera dueño de su superficie.
  // Tocar "Revelar" cierra deliberadamente la escalera: muestra la respuesta y
  // no hay más niveles después (doRevealFromHelp() ya existía para esto,
  // estaba sin llamador — se reusa, no se inventa nada).
  BottomSheet.open('tutor-menu', '', 'normal', exhausted
    ? { label: 'Revelar', onClick: () => doRevealFromHelp() }
    : { label: 'Más ayuda', onClick: () => openHelpMenu(true) });
  riseTutor(); // Pieza 1: el ascenso ya no es automático de open() — quien abre lo pide
  setExerciseState(EX_STATE.EXPLICACION, 'openHelpMenu');
  // Sin esto, agotar las 3 capas no revela "Revelar" en el footer hasta el
  // próximo evento que lo refresque por otra vía (bug real encontrado
  // verificando esta fase, no en el encargo original) — mismo llamado que
  // ya hacía requestHelp() en cada avance.
  updateHelpUI();
}
// Pieza 1 (2026-08-26) — "Revelar" desde adentro de la escalera de ayuda:
// mismo mecanismo exacto que ya usaba el botón "Ver respuesta" de
// openErrorSheet() (retirado, ver comentario en esa función) — cierra el
// sheet directo (no closeHelp(), ese cierre general es para tutor-menu sin
// acción especial) y llama doReveal(), que ya cablea su propia transición.
function doRevealFromHelp(){
  BottomSheet.close();
  state._helpPanelSource=null;
  doReveal();
}
// Reusa el lenguaje visual exacto de renderScaffoldLayer() (pasos de
// ejemplo, cuerpo de texto — mismas clases CSS) pero devuelve HTML para el
// sheet en vez de acumular una tarjeta en #scaffold-zone. Pieza 1
// (2026-08-26): sacado el ícono chico (scaffold-hint-hero, TUTOR.imgHint) —
// redundante con el tutor grande que ya sube sobre este mismo sheet.
function renderHelpLayerHtml(layer, n, total) {
  let h = '<div class="scaffold-card-label">'+escHtml(layer.label)+' <span class="step-count">'+n+'/'+total+'</span></div>';
  if (layer.kind==='example' && layer.example) {
    if (layer.example.label) h += '<div class="scaffold-card-body">'+escHtml(layer.example.label)+'</div>';
    (layer.example.steps||[]).forEach(function(s){
      h += '<div class="scaffold-step">'+(s.op?'<span class="op">'+escHtml(s.op)+(s.reason?' — '+escHtml(s.reason):'')+'</span>':'')+escHtml(s.math||'')+'</div>';
    });
  } else {
    h += '<div class="scaffold-card-body">'+escHtml(layer.body||'')+'</div>';
  }
  return h;
}
// "¿Por qué?" (Fase 4/10, 2026-08-24) — reemplaza el expand INLINE
// (.feedback-extra { max-height:0→300px }, literalmente "expandir la
// pantalla del ejercicio", instrucción explícita del Director de sacarlo)
// por este mismo bottom sheet compartido. Solo existe en el camino
// CORRECTO (gateado en showFeedback(), sin cambios de esta fase) — lee
// ex.feedbackExtra directo del ejercicio activo en vez de depender de un
// nodo intermedio en el DOM.
function openWhySheet(){
  const exs=getActiveExercises(state.currentModule), ex=exs[state.currentExerciseIndex];
  if(!ex || !ex.feedbackExtra) return;
  // Limpieza (2026-09-16): el auto-avance de 5s que esta línea cancelaba ya
  // no existe (retirado en handleConfirm(), ver su comentario) — la
  // cancelación era una dependencia funcional exclusiva de ese timer, sin
  // ningún otro rol acá, así que se retira con él. Nada más de esta función
  // cambia.
  // Fase 6/10 (Parte J, 2026-08-24): "¿Por qué?" se puede abrir desde
  // CORRECTA (Fase 4) o desde REVELADA (Fase 6, tras revelar) — cerrar
  // tiene que volver a CUAL DE LAS DOS era, no a un valor fijo, o la máquina
  // de estados queda mintiendo (diría "acertó" cuando en realidad reveló).
  // Se captura el estado ACTUAL (todavía sin pisar) antes de transicionar.
  state._helpReturnState = state.exerciseState;
  // Especificación Bottom Sheets + Tutor (2026-09-05, corrección
  // fundamental): mismo criterio que openHelpMenu() — el Tutor reemplaza el
  // Sheet de origen (verde/gris), nunca se apila; #confirm-btn (mismo nodo,
  // ver setPrimaryCTA()) se compacta y flota, nunca se clona.
  {
    const fzOrigin = document.getElementById('feedback-zone');
    if (fzOrigin.classList.contains('visible')) {
      fzOrigin.classList.add('tutor-open');
      enterCompactCTA();
    }
  }
  // Fase 7/10 (2026-08-24): el contenido pasa por el componente Explicación
  // — hoy ex.feedbackExtra es siempre un string (todo el contenido real que
  // existe), degrada a CORTA automáticamente, sin cambiar nada de lo que ya
  // funciona. "Lo entiendo"/cerrar el sheet de cualquier forma hacen lo
  // mismo: closeHelp() ya sabe restaurar _helpReturnState (sin cambios).
  // Re-especificación Fase 7, Parte 1 (2026-08-25): comprensionPregunta/Si/No
  // — hoy solo declarados en `ing-04-mi-familia` m0-n1 (ING4-000008 a 011).
  // Sin el campo, `comprension` queda null y renderExplicacion() toma el
  // camino de siempre, sin cambios.
  const comprension = ex.comprensionPregunta ? { pregunta: ex.comprensionPregunta, si: ex.comprensionSi, no: ex.comprensionNo } : null;
  const form = renderExplicacion(ex.feedbackExtra, () => closeHelp(), comprension);
  BottomSheet.open('why-sheet', '', form); // Pieza 1 (2026-08-26): sin subtítulo — ver comentario en BottomSheet.open()
  riseTutor(); // Pieza 1: el ascenso ya no es automático de open() — quien abre lo pide
  setExerciseState(form==='larga' ? EX_STATE.EXPLICACION_EXTENSA : EX_STATE.EXPLICACION, 'openWhySheet');
}
// Pieza 1 — Separar Feedback de Tutor (2026-08-26): openErrorSheet() deja
// de abrir el sheet compartido (retirada la fuente 'error-sheet' de
// BottomSheet por completo) — arma la tarjeta liviana "Incorrecto" en
// #feedback-zone, mismo criterio que showFeedback()/doReveal() (resultado
// ≠ tutor, son 2 sistemas distintos — ver comentario del CSS). "Intentar de
// nuevo" reintenta directo (retryExercise(), ya no hay sheet que cerrar
// primero). "Necesitás ayuda" abre el sheet compartido con la escalera
// (openHelpMenu()) y sube el tutor — acción EXPLÍCITA del alumno, no efecto
// automático de errar (Director: "el sheet + tutor solo suben por acción
// explícita: tocar el tutor, tocar Necesitás ayuda, o tocar ¿Por qué?").
// Especificación Bottom Sheets + Tutor (2026-09-05, autorización explícita
// del Director): 2 correcciones sobre esta función.
// 1) Jerarquía de botones: "Intentar de nuevo" pasa a ser la PRIMARIA
//    (antes tenía la clase secundaria por error de la implementación
//    anterior — confirmado visualmente en el navegador, no solo leyendo
//    código). La acción de ayuda pasa a secundaria.
// 2) La acción secundaria ya no es fija ("Necesitás ayuda" siempre") — usa
//    el MISMO gating real que ya usa updateHelpUI() para #reveal-btn
//    (state.helpLevel >= state.helpLayers.length) — 2 ejes independientes,
//    por decisión explícita del Director: disponibilidad de reintento
//    (maneja quién llama a esta función, ver canRetry en handleConfirm())
//    y disponibilidad de ayuda (gestionada acá). No se creó ningún
//    contador nuevo — se reusa exactamente el mismo dato que ya gatea
//    #reveal-btn en el footer.
// CORRECCIÓN FUNDAMENTAL (2026-09-05, auditoría del Director): el CTA
// principal ya NO se crea de nuevo acá — #confirm-btn es una única entidad
// visual/lógica que cambia de texto/color/función según el estado, nunca se
// oculta ni se duplica. El Sheet aporta solo el mensaje y la acción
// SECUNDARIA (que sí es contenido propio del resultado, no el CTA). El
// footer (con #confirm-btn y el tutor-strip) queda siempre visible, por
// encima del Sheet (ver z-index de .feedback-zone) — nada se oculta ahí, así
// que su forma nunca cambia y Spike no se corre de lugar (causa real del
// corrimiento reportado: ocultar hermanos en un flex container cambiaba la
// altura del footer).
function openErrorSheet(ex){
  const fz=document.getElementById('feedback-zone');
  fz.innerHTML='';
  // Cabecera de estado + acción secundaria en la MISMA fila (2026-09-07,
  // decisión del Director): la secundaria es una acción contextual del
  // feedback, no contenido que merezca una línea propia. Además deja la
  // esquina derecha reservada, así "Necesitás ayuda" puede transformarse en
  // "Revelar" sin que el Sheet cambie de estructura.
  const headrow=document.createElement('div'); headrow.className='feedback-headrow';
  const header=document.createElement('div'); header.className='feedback-header wrong'; header.textContent='No del todo';
  headrow.appendChild(header);
  fz.appendChild(headrow);
  const text=document.createElement('div'); text.className='feedback-text';
  const _msgErr = ex.feedbackWrong || pickMsg(TUTOR.mensajesIncorrecto);
  // §8/§9 (2026-09-06): si hay un diagnóstico concreto del error (hoy solo
  // `order`), ÉSE es el mensaje principal y la explicación autorada baja a
  // segunda capa. Mismo criterio en los 2 caminos de error del Motor.
  text.textContent = primaryWrongText(_msgErr);
  fz.appendChild(text);
  appendComparativeBlock(fz, false); // hay reintento por delante: no se revela el orden correcto
  const hasHelp = state.helpLayers && state.helpLayers.length>0;
  const helpExhausted = !hasHelp || state.helpLevel>=state.helpLayers.length;
  // 2026-09-06: al sacar "Revelar" del footer (ver updateHelpUI()), este Sheet
  // pasa a ser la vía de revelación del camino del error. Antes toda esta
  // secundaria vivía adentro de `if (hasHelp)`, así que un ejercicio SIN
  // escalera de ayuda se quedaba sin ninguna forma de revelar en cuanto el
  // botón del footer dejó de mostrarse. Se replica exactamente el gate que
  // usaba updateHelpUI() para ese caso (kinds no revelables + freeAttempt),
  // en vez de inventar uno nuevo.
  const noReveal=['memory','free','slides','concept'];
  // isEvalModule() cubre evaluación Y Skill Check (ver su comentario): en esas
  // instancias "Revelar" tampoco corresponde — es una ayuda, y la más fuerte
  // de todas. Sin esto, al quitarle la escalera al Skill Check la secundaria
  // caía directo en "Revelar", que es peor que la pista que acabábamos de
  // sacar.
  const puedeRevelar = !noReveal.includes(ex.kind) && !ex.freeAttempt && !isEvalModule(state.currentModule);
  if (!helpExhausted || puedeRevelar) {
    const secBtn=document.createElement('button'); secBtn.type='button'; secBtn.className='feedback-zone-secondary-btn';
    if (!helpExhausted) { secBtn.textContent='Necesitás ayuda'; secBtn.onclick=()=>openHelpMenu(); showHelpBtnFirstUseHint(); }
    else { secBtn.textContent='Revelar'; secBtn.onclick=()=>doReveal(); }
    // Fix pointer-events (2026-09-16, verificación manual CS-03): mismo
    // defecto y misma corrección que showFeedback() — headrow vive dentro
    // de .feedback-zone (pointer-events:none); envolver en
    // .feedback-zone-actions (ya existe, revierte a pointer-events:auto)
    // recupera el click sin tocar .feedback-zone globalmente. Este es el
    // camino real que toma el PRIMER error de un kind RETRYABLE (mc/tf) —
    // el mismo bug reportado para showFeedback() lo tenía también acá.
    const secActions=document.createElement('div'); secActions.className='feedback-zone-actions';
    secActions.appendChild(secBtn);
    headrow.appendChild(secActions); // en la cabecera, no en una fila propia
  }
  setPrimaryCTA('Intentar de nuevo', 'state-wrong', () => retryExercise(ex));
  showResultSheet(fz, 'wrong-fb'); // el CTA cambia ANTES de animar — ver showResultSheet()
  setExerciseState(EX_STATE.INCORRECTA, 'openErrorSheet');
}
// "Probar de vuelta" (Fase 5/10, 2026-08-24) — reintento real: re-habilita
// SOLO las alternativas que no están en state.rejectedOptions (las que ya
// demostraron ser incorrectas quedan deshabilitadas de verdad, no solo
// grises — mismo patrón .disabled=true que ya bloquea click y teclado en
// botones nativos). Mismo bloque por kind que ANTES vivía inline en
// handleConfirm() (Hallazgo del plan de fases) — movido acá tal cual,
// solo agregando el filtro de rejectedOptions por kind con opciones
// discretas (mc/mc-multi/tf/word-bank/error-find). fill no tiene "opción"
// que rechazar (texto libre) — sin cambios ahí. order queda fuera de
// alcance a propósito (no es una elección discreta, es una secuencia) —
// mismo bloque de siempre, intacto.
function retryExercise(ex){
  // Corrección 2026-09-06 (hallazgo real de la auditoría de estado): el CTA
  // persistente sigue siendo el mismo botón cuando el Tutor está abierto, así
  // que "Intentar de nuevo" se puede tocar DESDE adentro del Tutor. Sin este
  // cierre, el reintento arrancaba (se ocultaba el Sheet, se re-habilitaban
  // las opciones) pero el panel quedaba abierto tapando el ejercicio: el
  // alumno no podía responder. Mismo mecanismo y misma guarda que ya usa
  // doReveal() para el caso simétrico — no se inventa nada nuevo.
  // goToNextExercise() no lo necesita: sale por renderExercise()/goToScreen(),
  // que ya cierran el sheet fantasma.
  if (document.getElementById('help-overlay').classList.contains('open')) {
    BottomSheet.close();
    state._helpPanelSource = null;
    state._helpReturnState = null;
  }
  setExerciseState(EX_STATE.REINTENTO, 'retryExercise'); // invariante #5: "al volver al ejercicio" → REINTENTO
  state.answered=false;
  // Especificación Bottom Sheets + Tutor (2026-09-05, hallazgo real en
  // regresión de natural-retry.spec.js): "Intentar de nuevo" vuelve a
  // mostrar el ejercicio para responder — el Sheet de error se oculta y el
  // footer (Confirmar/Saltar) reaparece. Antes esto no hacía falta porque
  // #confirm-btn.hidden no tenía ninguna regla CSS (gap preexistente,
  // corregido en esta misma fase) — con la regla real puesta, sin este
  // reset "Intentar de nuevo" dejaba Confirmar oculto para siempre.
  document.getElementById('feedback-zone').className = 'feedback-zone';
  document.getElementById('confirm-btn').classList.remove('hidden');
  document.getElementById('skip-btn').classList.remove('hidden');
  if(ex.kind==='mc'){
    document.querySelectorAll('.option-btn').forEach((b,i)=>{
      if(state.rejectedOptions.has(i)){ b.disabled=true; b.classList.add('rejected'); b.classList.remove('selected'); return; }
      b.disabled=false; b.classList.remove('wrong','correct','selected');
    });
    state.selectedOption=null; disableConfirm();
  } else if(ex.kind==='mc-multi'){
    document.querySelectorAll('.checkbox-btn').forEach((b,i)=>{
      if(state.rejectedOptions.has(i)){ b.disabled=true; b.classList.add('rejected'); b.classList.remove('selected'); b.querySelector('.checkbox-box').textContent=''; return; }
      b.disabled=false; b.classList.remove('wrong','correct','selected'); b.querySelector('.checkbox-box').textContent='';
    });
    state.mcMultiSelected=new Set(); disableConfirm();
  } else if(ex.kind==='tf'){
    document.querySelectorAll('.tf-btn').forEach(b=>{
      const isTrue=b.textContent.includes('Verdadero');
      if(state.rejectedOptions.has(isTrue)){ b.disabled=true; b.classList.add('rejected'); b.classList.remove('selected'); return; }
      b.disabled=false; b.classList.remove('wrong','correct','selected');
    });
    state.selectedOption=null; disableConfirm();
  } else if(ex.kind==='fill'){
    const inp=document.querySelector('#exercise-input-area .text-input');
    if(inp){inp.disabled=false;inp.classList.remove('wrong','correct');inp.value='';inp.dispatchEvent(new Event('input'));inp.focus();}
    disableConfirm();
  } else if(ex.kind==='mundo'){
    PDP_MUNDO.reintentar(ex);
  } else if(ex.kind==='word-bank'){
    const blank=document.getElementById('wb-blank');
    if(blank){blank.textContent='___';blank.className='fill-blank';}
    document.querySelectorAll('.word-chip').forEach(c=>{
      const idx=parseInt(c.dataset.idx);
      if(state.rejectedOptions.has(idx)){ c.classList.add('rejected'); c.disabled=true; return; }
      c.classList.remove('used','selected'); c.disabled=false;
    });
    state.wordBankSelected=null; disableConfirm();
  } else if(ex.kind==='error-find'){
    document.querySelectorAll('.error-word').forEach(s=>{
      const i=parseInt(s.dataset.idx);
      s.classList.remove('wrong','correct','selected');
      if(state.rejectedOptions.has(i)){ s.classList.add('rejected'); s.onclick=null; return; }
      s.onclick=()=>{if(state.answered||state.rejectedOptions.has(i))return;document.querySelectorAll('.error-word').forEach(x=>x.classList.remove('selected'));state.errorFindSelected=i;s.classList.add('selected');enableConfirm();};
    });
    const cf=document.getElementById('error-correction-field');
    if(cf){cf.disabled=false;cf.classList.remove('wrong','correct');cf.value='';}
    state.errorFindSelected=null; disableConfirm();
  } else if(ex.kind==='order'){
    // Hallazgo 6 (2026-08-24, Parte H): rama de reinicio para 'order' —
    // el bloque de arriba en handleConfirm() ya pinta/deshabilita los
    // chips sin condicionar (mismo patrón que fill/error-find); esta
    // rama lo deshace cuando corresponde reintentar. Mismo código que
    // usa el render inicial (chip.onclick), no uno nuevo. Fuera de
    // alcance de rejectedOptions (Fase 5/10): no es una elección discreta.
    // 2026-10-27 (nota del Director: «no deja corregir las opciones que elegiste»): lo que quedó bien puesto desde el principio hasta el primer error se mantiene; el resto vuelve a las fichas.
    let keep=0; while(keep<state.orderSelected.length && state.orderSelected[keep]===ex.correctOrder[keep]) keep++;
    const quedan=state.orderSelected.slice(0,keep);
    state.orderSelected=[];
    document.getElementById('order-slots').innerHTML='';
    document.querySelectorAll('.word-chip').forEach(c=>{
      c.classList.remove('used');
      const origIdx=parseInt(c.dataset.idx);
      c.onclick=()=>{if(state.answered)return;selectOrderWord(origIdx,ex);};
    });
    quedan.forEach(i=>selectOrderWord(i,ex));
    disableConfirm();
  }
}
function showSupportPanel(html){
  document.getElementById('support-content').innerHTML=html;
  document.getElementById('support-overlay').classList.add('open');
}
function closeSupportPanel(e){
  if(!e||e.target===document.getElementById('support-overlay'))
    document.getElementById('support-overlay').classList.remove('open');
}
// Drag-to-dismiss (Rediseño ISSEN Parte D, E3 parcial — la parte barata
// identificada en el mapeo de pasos 3-5, 2026-07-21). Genérico: sirve para
// cualquier bottom sheet con drag-handle (.help-panel), no repite lógica
// por panel. Solo arranca el arrastre si el toque empieza en la franja de
// arriba (handle + encabezado) — así no interfiere con hacer scroll al
// contenido del panel (ej. la tabla pitagórica).
function enableSheetDrag(panel, onClose){
  if(!panel) return;
  // Expansión hacia arriba (2026-09-16): capacidad EXCLUSIVA del Tutor Sheet.
  // Esta misma función la usa también #support-panel (Tabla pitagórica, ver
  // sus 2 llamadores) y ese panel debe conservar exactamente el comportamiento
  // de siempre — solo arrastre hacia abajo para cerrar. Por eso el gate por id
  // en vez de un parámetro nuevo: es el diff más chico y no toca los llamadores.
  const expandable = panel.id === 'help-panel';
  let dragging=false, startY=0, currentY=0, startH=0;
  panel.addEventListener('pointerdown', e=>{
    const rect=panel.getBoundingClientRect();
    if(e.clientY - rect.top > 60) return;
    dragging=true; startY=e.clientY; currentY=0; startH=rect.height;
    panel.style.transition='none';
    panel.setPointerCapture(e.pointerId);
  });
  panel.addEventListener('pointermove', e=>{
    if(!dragging) return;
    const dy = e.clientY - startY;
    // Hacia abajo (dy>=0) o panel no expandible: comportamiento intacto.
    if(!expandable || dy >= 0){
      currentY=Math.max(0, dy);
      panel.style.transform=`translateY(${currentY}px)`;
      return;
    }
    // Hacia arriba: crece el propio panel en vez de desplazarlo. Nunca pasa
    // del techo de política (misma fuente que el cálculo automático), así que
    // no puede invadir el footer ni salirse del viewport. `currentY` queda en 0
    // para que endDrag() no lo confunda con un gesto de cierre.
    currentY = 0;
    panel.style.transform = '';
    const target = Math.round(Math.min(helpPanelPolicyMaxPx(), startH - dy));
    // Se fija PISO además del techo: `max-height` solo es un máximo, y el panel
    // es height:auto — verificado en runtime, subir el techo con el contenido
    // ya entrando no lo agranda ni un píxel. El piso es lo que hace que el
    // gesto se vea, y es lo que permitirá reservar lugar para una conversación
    // que todavía no llegó (#help-content es flex:1 y estira solo).
    // Queda registrado en state para que el recálculo automático lo respete en
    // vez de pisarlo; syncHelpPanelMaxHeight() lo limpia al cerrarse el sheet.
    state._helpPanelUserExpandedPx = target;
    panel.style.maxHeight = target + 'px';
    panel.style.minHeight = target + 'px';
    // El asset de Spike está anclado contra el rect del panel: si el panel
    // cambia de alto hay que recalcular su destino o queda desfasado.
    // riseTutor() ya es idempotente para esto — cuando el strip ya está
    // `rising` solo re-ejecuta strip._doRise() contra la geometría nueva.
    if(typeof riseTutor === 'function') riseTutor();
  });
  function endDrag(){
    if(!dragging) return;
    dragging=false;
    panel.style.transition='';
    panel.style.transform='';
    if(currentY > 80) onClose();
  }
  panel.addEventListener('pointerup', endDrag);
  panel.addEventListener('pointercancel', endDrag);
}
function closeHelp(e){
  if(!e||e.target===document.getElementById('help-overlay')){
    // Fase 7/10 (2026-08-24) — mecánica de cierre movida al primitivo.
    // Corrección 2026-09-06: restaurar el Sheet de resultado (quitar
    // .tutor-open) y devolver #confirm-btn al footer (exitCompactCTA())
    // TAMBIÉN vive ahora adentro de BottomSheet.close() — ver el comentario
    // de causa raíz ahí. Se sacaron de acá para que no haya dos dueños de la
    // misma responsabilidad: este camino queda cubierto igual.
    BottomSheet.close();
    // Invariante #5, Fase 4/10 (2026-08-24): cerrar "¿Por qué?" vuelve al
    // estado de origen — CORRECTA (Fase 4) o REVELADA (Fase 6/10,
    // 2026-08-24: "¿Por qué?" ahora también se abre tras revelar). Se
    // restaura _helpReturnState, capturado por openWhySheet() al abrir, en
    // vez de un valor fijo — si no, la máquina de estados mentiría (diría
    // "acertó" cuando en realidad reveló). Cerrar el menú del tutor (Fase 3)
    // no tiene transición propia — sigue sin tenerla, ver comentario
    // completo arriba de openHelpMenu().
    const source = state._helpPanelSource;
    state._helpPanelSource = null;
    if (source === 'why-sheet') {
      setExerciseState(state._helpReturnState || EX_STATE.CORRECTA, 'closeHelp:why-sheet');
      state._helpReturnState = null;
      return;
    }
    // Rama muerta desde Pieza 1 (2026-08-26): 'error-sheet' dejó de existir
    // como fuente de BottomSheet — openErrorSheet() ya no abre el sheet
    // (arma la tarjeta liviana #feedback-zone, "Intentar de nuevo" llama
    // retryExercise(ex) directo, sin pasar por acá). Nada vuelve a setear
    // _helpPanelSource='error-sheet' — rama nunca alcanzable. No se borra
    // (no reconstruir), documentado para quien retome esa limpieza.
    if (source === 'error-sheet') {
      const exs=getActiveExercises(state.currentModule), ex=exs[state.currentExerciseIndex];
      if (ex) retryExercise(ex);
    }
  }
}

/* ── Nivel 3: Tutor reactivo ── */

/* ══ Sistema Guided ══════════════════════════════════════════════════
   Muestra mensajes del tutor en momentos específicos del ejercicio.
   Activado con guided:true en cualquier kind del DATA ZONE.

   Eventos disponibles:
   'start'              → al mostrar el ejercicio
   'correct'            → al responder bien (todos los tipos)
   'wrong'              → al responder mal (todos los tipos)
   'hint'               → cuando aparece la pista (RETRYABLE)
   'complete'           → al completar el ejercicio
   'op:correct'         → eligió la operación correcta (eq-linear)
   'op:wrong'           → eligió operación incorrecta (eq-linear)
   'step:N:correct'     → paso N correcto (eq-linear, frac-steps)
   'step:N:wrong'       → paso N incorrecto
   'column:N:correct'   → columna N correcta (sum-columns, rest-columns, div-larga)
   'column:N:wrong'     → columna N incorrecta
═══════════════════════════════════════════════════════════════════ */
function guidedMsg(when) {
  const exs = getActiveExercises(state.currentModule);
  const ex  = exs[state.currentExerciseIndex];
  if (!ex || !ex.guided || !ex.guidedMessages) return;

  const msgs = ex.guidedMessages;

  // Buscar mensaje exacto primero
  let match = msgs.find(m => m.when === when);

  // Si no hay exacto, buscar comodines
  // 'step:N:correct' → buscar 'step:correct' como fallback
  if (!match) {
    const parts = when.split(':');
    if (parts.length === 3) {
      match = msgs.find(m => m.when === parts[0]+':'+parts[2]);
    }
  }

  if (!match) return;

  // Pantalla de tabla con cartel de madera (2026-10-28, pedido del Director): el cartel ya
  // da la consigna y el aviso de arranque la repetía con otras palabras; solo el de arranque.
  if (when === 'start' && document.documentElement.classList.contains('pdp-ej-tabla')) return;

  // Guardrail de contenido (2026-09-22, hallazgo real: un mensaje guiado
  // quedó cargado con una sola letra suelta, probablemente un error de
  // contenido, no de este código). No se persigue esa instancia puntual sin
  // evidencia — se blinda el mecanismo en general: un texto sospechosamente
  // corto no se muestra nunca, para cualquier ejercicio presente o futuro.
  if (typeof match.text !== 'string' || match.text.trim().length < 4) {
    console.warn('[guidedMsg] texto sospechoso, no se muestra:', ex.id, when, match.text);
    return;
  }

  const tz = document.getElementById('tutor-zone');
  const tt = document.getElementById('tutor-text');
  if (!tz || !tt) return;

  // Mostrar el mensaje en la zona del tutor
  tz.style.display = 'flex';
  tz.className = 'tutor-zone guided';
  tt.innerHTML = '';
  const span = document.createElement('span');
  span.textContent = match.text;
  tt.appendChild(span);
}

function checkTutorReaction(isCorrect){
  if(isCorrect){
    state.consecutiveWrong=0;
    // Racha de 5: celebración del tutor solo en respuesta correcta (R-005: tutor mudo en errores)
    if(state.streak>0&&state.streak%5===0){
      // Rediseño visual calibrado, Fase 9 (2026-07-28) — hallazgo de la
      // regresión final: si este es el ÚLTIMO ejercicio del módulo,
      // goToNextExercise() va a disparar showModuleEnd()/showCelebration()
      // apenas se avance — "momento más grande" de los 3 triggers, según
      // el propio plan. Chequeo predictivo (misma cuenta que usa
      // goToNextExercise() para decidir lo mismo) ANTES de mostrar el
      // banner de racha, sin mecanismo elaborado: si coincide, el cierre
      // de módulo gana y el banner de racha se suprime.
      const _exsForMilestone = getActiveExercises(state.currentModule);
      const _isLastOfModule = (state.currentExerciseIndex+1) >= _exsForMilestone.length;
      if(!_isLastOfModule){
        // Rediseño visual calibrado, Fase 7 (2026-07-28): el banner de
        // hito REEMPLAZA flashTutorZone('streak',...) acá — no conviven
        // los dos, decisión ya tomada con Dirección.
        showMilestoneBanner(pickMsg(TUTOR.mensajesRacha,{n:state.streak}));
      }
    }
  } else {
    state.consecutiveWrong++;
    // R-005: tutor no reacciona a errores individuales — el sistema de andamiaje (hint/feedbackExtra) cubre la ayuda
  }
}
// Rediseño visual calibrado, Fase 7 (2026-07-28): banner de hito —
// mismo timing de referencia que flashTutorZone() (4s), auto-dismiss,
// sin bloquear #confirm-btn (pointer-events:none en el banner, y vive
// arriba de la pantalla, lejos del footer). Reusa la pose imgCelebrate
// de la Fase 4 (mismo momento visual en los 3 disparadores: racha,
// mitad de módulo, cierre de módulo — este último ya la tiene en
// #screen-celebration desde la Fase 4, sin duplicar acá).
function showMilestoneBanner(message){
  const banner=document.getElementById('milestone-banner');
  const text=document.getElementById('milestone-banner-text');
  text.textContent=message;
  banner.classList.add('show');
  clearTimeout(state._milestoneBannerTimer);
  state._milestoneBannerTimer=setTimeout(()=>{ banner.classList.remove('show'); }, 4000);
}
// flashTutorZone() removida en Fase 9 del rediseño visual calibrado
// (2026-07-28) — sin call sites desde la Fase 7 (el banner de hito
// reemplazó su única llamada, la de racha). Autorizado por Dirección
// explícitamente para el cierre consolidado de este plan.

/* ── mc ── */
function renderMC(ex,area) {
  const list=document.createElement('div'); list.className='options-list';
  ex.options.forEach((opt,i)=>{
    const btn=document.createElement('button'); btn.className='option-btn';
    btn.innerHTML=`<span class="option-letter">${'ABCD'[i]}</span>${escHtml(opt)}`;
    btn.onclick=()=>{if(state.answered||state.rejectedOptions.has(i))return;state.selectedOption=i;document.querySelectorAll('.option-btn').forEach((b,j)=>b.classList.toggle('selected',j===i));enableConfirm();}; // SFX de interacción (2026-09-17): se movió a handleConfirm() — la acción principal es confirmar, no elegir; evita sonar 2 veces por respuesta
    list.appendChild(btn);
  });
  area.appendChild(list);
  state.revealFn=()=>{
    state.selectedOption=ex.correct;
    document.querySelectorAll('.option-btn').forEach((b,j)=>b.classList.toggle('selected',j===ex.correct));
    enableConfirm();
  };
}

/* ── mc-multi ── */
function renderMCMulti(ex,area) {
  const hint=document.createElement('div'); hint.className='mc-multi-hint';
  hint.textContent='Seleccioná todas las que correspondan antes de confirmar.';
  area.appendChild(hint);
  const list=document.createElement('div'); list.className='options-list';
  ex.options.forEach((opt,i)=>{
    const btn=document.createElement('button'); btn.className='checkbox-btn';
    btn.innerHTML=`<span class="checkbox-box"></span>${escHtml(opt)}`;
    btn.onclick=()=>{
      if(state.answered||state.rejectedOptions.has(i))return;
      if(state.mcMultiSelected.has(i)){state.mcMultiSelected.delete(i);btn.classList.remove('selected');btn.querySelector('.checkbox-box').textContent='';}
      else{state.mcMultiSelected.add(i);btn.classList.add('selected');btn.querySelector('.checkbox-box').textContent='✓';}
      state.mcMultiSelected.size>0?enableConfirm():disableConfirm(); // SFX de interacción (2026-09-17): movido a handleConfirm(), ver mc
    };
    list.appendChild(btn);
  });
  area.appendChild(list);
  state.revealFn=()=>{
    state.mcMultiSelected=new Set(ex.correct);
    document.querySelectorAll('.checkbox-btn').forEach((b,i)=>{
      const ok=ex.correct.includes(i);
      b.classList.toggle('selected',ok);
      b.querySelector('.checkbox-box').textContent=ok?'✓':'';
    });
    enableConfirm();
  };
}

/* ── tf ── */
function renderTF(ex,area) {
  const row=document.createElement('div'); row.className='tf-row';
  [{val:true,icon:'✓',label:'Verdadero'},{val:false,icon:'✗',label:'Falso'}].forEach(({val,icon,label})=>{
    const btn=document.createElement('button'); btn.className='tf-btn';
    btn.innerHTML=`<span class="tf-icon">${icon}</span>${label}`;
    btn.onclick=()=>{if(state.answered||state.rejectedOptions.has(val))return;state.selectedOption=val;document.querySelectorAll('.tf-btn').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');enableConfirm();}; // SFX de interacción (2026-09-17): movido a handleConfirm(), ver mc
    row.appendChild(btn);
  });
  area.appendChild(row);
  state.revealFn=()=>{
    state.selectedOption=ex.correct;
    document.querySelectorAll('.tf-btn').forEach(btn=>{
      const isCorrect=(btn.textContent.includes('Verdadero')&&ex.correct)||(btn.textContent.includes('Falso')&&!ex.correct);
      btn.classList.toggle('selected',isCorrect);
    });
    enableConfirm();
  };
}

/* ── fill ── */
/* ── free modo B · criterios declarados (2026-10-19, pedido del Director: más práctica de escritura) ──
   El alumno escribe un texto corto con sus palabras; al confirmar, el Motor revisa CRITERIOS declarados y le muestra cuáles cumplió y cuáles no (con el mensaje de lo que falta). No califica: el resultado sigue siendo `seen` (modo C).
   rules:[{ tiene:['i\'m maya','i am maya'], etiqueta:'Dije mi nombre con I\'m.', falta:'Falta decir cómo te llamás: I\'m y tu nombre.' },     // cumple si aparece ALGUNA alternativa (palabra o frase completa)
          { no:['have'], etiqueta:'No usé tener para la edad.', sobra:'La edad no se dice con tener.' },                                  // falla si aparece ALGUNA
          { patron:'\\b(\\d+|twelve)\\b', etiqueta:'Dije mi edad.', falta:'Falta tu edad.' }],                                            // expresión regular sobre el texto normalizado
   minPalabras (opcional) + etiquetaMin / mensajeCorto. `modelo` es la respuesta de referencia (el control de autoría comprueba que cumple sus propias reglas) y `feedback` es lo que se muestra.
   Texto normalizado: minúsculas, sin tildes, apóstrofes unificados, sin puntuación. */
function textoLibreNormalizado(s) {
  return normalize(s).replace(/[.,?!;:¿¡"()]+/g,' ').replace(/\s+/g,' ').trim();
}
function evaluarCriterios(ex, crudo) {
  const txt = textoLibreNormalizado(crudo), pad = ' ' + txt + ' ';
  const palabras = txt ? txt.split(' ').length : 0, out = [];
  if (ex.minPalabras) out.push({ ok: palabras >= ex.minPalabras, texto: palabras >= ex.minPalabras ? (ex.etiquetaMin || 'Escribí todo lo que pedía la consigna.') : (ex.mensajeCorto || 'Escribí un poco más.') });
  for (const r of (ex.rules||[])) {
    let ok = true;
    if (r.tiene) ok = r.tiene.some(a => pad.includes(' ' + textoLibreNormalizado(a) + ' '));
    else if (r.no) ok = !r.no.some(a => pad.includes(' ' + textoLibreNormalizado(a) + ' '));
    else if (r.patron) ok = (new RegExp(r.patron, 'i')).test(pad);
    out.push({ ok, texto: ok ? (r.etiqueta || 'Cumplido.') : (r.falta || r.sobra || 'Falta algo de lo que pide la consigna.') });
  }
  return out;
}
function renderFill(ex,area) {
  // Dictado (2026-10-19): un fill con audio muestra el botón «Escuchar» arriba; el alumno escribe lo que oye. El texto del audio (vozEntrada) es la respuesta: no se muestra.
  if(ex.audio||ex.vozEntrada){ area.appendChild(crearBotonEscuchar(ex)); }
  const inp=document.createElement('input'); inp.type='text'; inp.className='text-input';
  inp.placeholder=ex.placeholder||'Escribí tu respuesta...';
  inp.setAttribute('autocomplete','off'); inp.setAttribute('autocorrect','off'); inp.setAttribute('spellcheck','false');
  ['input','keyup','change'].forEach(ev=>inp.addEventListener(ev,()=>inp.value.trim()?enableConfirm():disableConfirm()));
  state.revealFn=()=>{ PDP_PIZARRA.sobre(inp, ex.answer); inp.classList.add('revealed'); enableConfirm(); };
  const orc=document.documentElement.classList.contains('pdp-ej-rollo')?pdpFillOracion(ex):null;
  if(orc){
    const sd=document.createElement('div'); sd.className='fill-sentence'; const pt=orc.oracion.split('___');
    const blank=document.createElement('span'); blank.className='fill-blank'; blank.id='fill-blank'; blank.textContent='___';
    sd.appendChild(document.createTextNode(pt[0])); sd.appendChild(blank); if(pt.length>1) sd.appendChild(document.createTextNode(pt.slice(1).join('___')));
    pdpRollo(ex,area).appendChild(sd);
    const espejo=()=>{ const v=inp.value.trim()||(inp.classList.contains('revealed')?String(ex.answer):''); blank.textContent=v||'___'; blank.classList.toggle('filled',!!v); blank.classList.toggle('correct',inp.classList.contains('correct')||inp.classList.contains('revealed')); blank.classList.toggle('wrong',inp.classList.contains('wrong')); };
    ['input','keyup','change'].forEach(ev=>inp.addEventListener(ev,espejo));
    try{ new MutationObserver(espejo).observe(inp,{attributes:true,attributeFilter:['class']}); }catch(_){}
  }
  area.appendChild(inp); setTimeout(()=>inp.focus(),150);
}

/* ── sum-columns (suma con llevadas, corrección por columna) ──
   Ejercicio: { id, kind:'sum-columns', numA, numB, pregunta, feedback }
   A diferencia de los demás tipos, este se autoevalúa columna por columna en
   tiempo real, no de una sola vez al apretar Confirmar. El botón Confirmar
   solo se habilita cuando TODA la cuenta está resuelta, y en ese momento no
   vuelve a corregir nada — solo avanza (mismo patrón que 'free').
   state.sumColHadError guarda si hubo algún error en el camino, para que
   handleConfirm lo use al decidir el badge "Sin errores". */
