// Reloj SVG compartido por los demos clock-hour/clock-minutes (item 4.1,
// Fase 4, 2026-07-14 — Representación Idéntica): MISMO dibujo que
// renderClock() (la práctica real) — círculo, marcas, números 12/3/6/9,
// agujas por trigonometría — para que enseñanza y práctica se vean igual.
function buildClockFace(stage, hours, minutes){
  const displayH=(hours%12)||12, displayM=minutes||0;
  const cs=getComputedStyle(document.documentElement);
  const C_TXT=cs.getPropertyValue('--text-primary').trim();
  const C_BG =cs.getPropertyValue('--bg-card').trim();
  const C_PRI=cs.getPropertyValue('--primary').trim();
  const SIZE=180, CX=90, CY=90, R=78;
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
  svg.setAttribute('viewBox',`0 0 ${SIZE} ${SIZE}`);
  svg.setAttribute('width',SIZE); svg.setAttribute('height',SIZE); svg.setAttribute('class','clk-svg');
  const face=document.createElementNS('http://www.w3.org/2000/svg','circle');
  face.setAttribute('cx',CX); face.setAttribute('cy',CY); face.setAttribute('r',R);
  face.setAttribute('fill',C_BG); face.setAttribute('stroke',C_TXT); face.setAttribute('stroke-width','2.5');
  svg.appendChild(face);
  for(let i=0;i<12;i++){
    const angle=-Math.PI/2+i*(2*Math.PI/12);
    const major=i%3===0;
    const r1=major?R*0.8:R*0.87, r2=R*0.97;
    const mk=document.createElementNS('http://www.w3.org/2000/svg','line');
    mk.setAttribute('x1',(CX+r1*Math.cos(angle)).toFixed(1)); mk.setAttribute('y1',(CY+r1*Math.sin(angle)).toFixed(1));
    mk.setAttribute('x2',(CX+r2*Math.cos(angle)).toFixed(1)); mk.setAttribute('y2',(CY+r2*Math.sin(angle)).toFixed(1));
    mk.setAttribute('stroke',C_TXT); mk.setAttribute('stroke-width',major?'2.5':'1.5');
    svg.appendChild(mk);
    if(major){
      const num=[12,3,6,9][i/3];
      const t=document.createElementNS('http://www.w3.org/2000/svg','text');
      t.setAttribute('x',(CX+R*0.65*Math.cos(angle)).toFixed(1));
      t.setAttribute('y',(CY+R*0.65*Math.sin(angle)).toFixed(1));
      t.setAttribute('text-anchor','middle'); t.setAttribute('dominant-baseline','central');
      t.setAttribute('font-size','14'); t.setAttribute('font-weight','900'); t.setAttribute('fill',C_TXT);
      t.textContent=String(num); svg.appendChild(t);
    }
  }
  const hAng=-Math.PI/2+(displayH+displayM/60)*(2*Math.PI/12);
  const hHand=document.createElementNS('http://www.w3.org/2000/svg','line');
  hHand.setAttribute('x1',CX); hHand.setAttribute('y1',CY);
  hHand.setAttribute('x2',(CX+R*0.55*Math.cos(hAng)).toFixed(1)); hHand.setAttribute('y2',(CY+R*0.55*Math.sin(hAng)).toFixed(1));
  hHand.setAttribute('stroke',C_TXT); hHand.setAttribute('stroke-width','5'); hHand.setAttribute('stroke-linecap','round');
  hHand.setAttribute('class','clk-hand-hour');
  svg.appendChild(hHand);
  const mAng=-Math.PI/2+(displayM/60)*2*Math.PI;
  const mHand=document.createElementNS('http://www.w3.org/2000/svg','line');
  mHand.setAttribute('x1',CX); mHand.setAttribute('y1',CY);
  mHand.setAttribute('x2',(CX+R*0.78*Math.cos(mAng)).toFixed(1)); mHand.setAttribute('y2',(CY+R*0.78*Math.sin(mAng)).toFixed(1));
  mHand.setAttribute('stroke',C_PRI); mHand.setAttribute('stroke-width','3.5'); mHand.setAttribute('stroke-linecap','round');
  mHand.setAttribute('class','clk-hand-minute');
  svg.appendChild(mHand);
  const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');
  dot.setAttribute('cx',CX); dot.setAttribute('cy',CY); dot.setAttribute('r','4'); dot.setAttribute('fill',C_TXT);
  svg.appendChild(dot);
  stage.appendChild(svg);
  return {svg, hHand, mHand};
}
const DEMOS = {
  // carry — anima la suma con llevada, columna por columna, mostrando la llevada "viajar".
  carry: function(stage, p, step, after){
    const A=String(p.numA!=null?p.numA:28), B=String(p.numB!=null?p.numB:15);
    const n=Math.max(A.length,B.length)+1;
    const a=A.padStart(n,' ').split(''), b=B.padStart(n,' ').split('');
    const res=new Array(n).fill(''), carryAt=new Array(n).fill(''), sums=new Array(n).fill(null);
    let carry=0;
    for(let i=n-1;i>=0;i--){
      const da=a[i]===' '?0:+a[i], db=b[i]===' '?0:+b[i];
      if(a[i]===' '&&b[i]===' '&&carry===0) continue;
      const s=da+db+carry; sums[i]=s; res[i]=String(s%10); carry=Math.floor(s/10);
      if(carry>0&&i>0) carryAt[i-1]=String(carry);
    }
    const grid=document.createElement('div'); grid.className='cd-grid';
    grid.style.gridTemplateColumns='22px repeat('+n+', 36px)';
    const carryCells=[], resCells=[], aCells=[], bCells=[];
    function add(txt,cls){ const d=document.createElement('div'); d.className='cd-cell'+(cls?' '+cls:''); d.textContent=txt; grid.appendChild(d); return d; }
    add('','');
    for(let i=0;i<n;i++){ const c=document.createElement('div'); c.className='cd-carry'; c.textContent=carryAt[i]; grid.appendChild(c); carryCells.push(c); }
    add('','op'); for(let i=0;i<n;i++) aCells.push(add(a[i]===' '?'':a[i]));
    add('+','op'); for(let i=0;i<n;i++) bCells.push(add(b[i]===' '?'':b[i]));
    const line=document.createElement('div'); line.className='cd-line'; grid.appendChild(line);
    add('',''); for(let i=0;i<n;i++) resCells.push(add(''));
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.appendChild(grid); stage.appendChild(gridWrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);
    const activeCols=[];
    for(let i=n-1;i>=0;i--){ if(sums[i]!==null) activeCols.push(i); }
    activeCols.forEach((col,k)=>{
      const isLast=k===activeCols.length-1;
      const s=sums[col], da=a[col]===' '?0:+a[col], db=b[col]===' '?0:+b[col], carryIn=s-da-db;
      const hasCarryOut = col>0 && carryAt[col-1]!=='';
      step(()=>{
        aCells.forEach(c=>c.classList.remove('lit')); bCells.forEach(c=>c.classList.remove('lit'));
        aCells[col].classList.add('lit'); bCells[col].classList.add('lit');
        bubble.textContent = da+' + '+db + (carryIn>0?' + '+carryIn:'') + ' = ' + s;
        bubble.classList.add('show');
        after(()=>{
          resCells[col].textContent=res[col]; resCells[col].classList.add('result');
          if(hasCarryOut) carryCells[col-1].classList.add('show');
          if(isLast) after(()=>{
            bubble.classList.remove('show');
            aCells.forEach(c=>c.classList.remove('lit')); bCells.forEach(c=>c.classList.remove('lit'));
            resCells.forEach(c=>{ if(c.textContent) c.classList.add('lit'); });
          }, 300);
        }, 520);
      });
    });
  },
  // number-build — un número se arma por valor posicional (centenas + decenas + unidades).
  'number-build': function(stage, p, step){
    const num=p.number!=null?p.number:243;
    const h=Math.floor(num/100), d=Math.floor((num%100)/10), u=num%10;
    const parts=[];
    if(h||num>=100) parts.push({v:h*100, lbl:'centenas', cls:'pv-h'});
    if(h||d||num>=10) parts.push({v:d*10, lbl:'decenas', cls:'pv-t'});
    parts.push({v:u, lbl:'unidades', cls:'pv-u'});
    const wrap=document.createElement('div'); wrap.className='nb-wrap';
    const row=document.createElement('div'); row.className='nb-parts';
    const els=parts.map(pt=>{ const e=document.createElement('div'); e.className='nb-part '+pt.cls; e.style.opacity='0';
      e.innerHTML='<div class="nb-val">'+pt.v+'</div><div class="nb-lbl">'+pt.lbl+'</div>'; row.appendChild(e); return e; });
    wrap.appendChild(row);
    const eq=document.createElement('div'); eq.className='nb-eq'; wrap.appendChild(eq);
    stage.appendChild(wrap);
    parts.forEach((pt,i)=> step(()=>{ els[i].style.opacity='1'; els[i].classList.add('nb-pop'); }));
    step(()=>{ eq.textContent=parts.map(x=>x.v).join(' + ')+' = '+num; eq.classList.add('show'); });
  },
  // times-as-groups — la multiplicación como grupos iguales que se juntan.
  'times-as-groups': function(stage, p, step){
    const a=p.factorA!=null?p.factorA:4, b=p.factorB!=null?p.factorB:3;
    const wrap=document.createElement('div'); wrap.className='tg-wrap';
    const groups=document.createElement('div'); groups.className='tg-groups'; wrap.appendChild(groups);
    const total=document.createElement('div'); total.className='tg-total'; wrap.appendChild(total);
    const els=[];
    for(let g=0; g<b; g++){ const ge=document.createElement('div'); ge.className='tg-group'; ge.style.opacity='0';
      for(let i=0;i<a;i++){ const dot=document.createElement('div'); dot.className='tg-dot'; ge.appendChild(dot); }
      groups.appendChild(ge); els.push(ge); }
    stage.appendChild(wrap);
    for(let g=0; g<b; g++) step(()=>{ els[g].style.opacity='1'; els[g].classList.add('tg-pop'); });
    // captionOverride (Fase 5, item 5.5, 2026-07-20): mismo agrupamiento visual,
    // reusado para división (a×b puntos vistos como a×b÷a=b grupos) sin duplicar
    // el renderer — el texto de cierre pasa a describirlo quien lo usa.
    step(()=>{ total.textContent=p.captionOverride || (a+' × '+b+' = '+(a*b)); total.classList.add('show'); });
  },
  // fraction-split — un entero se parte en partes iguales y se sombrea el numerador.
  'fraction-split': function(stage, p, step){
    const num=p.numerator!=null?p.numerator:3, den=p.denominator!=null?p.denominator:4;
    const wrap=document.createElement('div'); wrap.className='fs-wrap';
    const fig=document.createElement('div'); fig.className='fs-fig fs-bar'; wrap.appendChild(fig);
    const label=document.createElement('div'); label.className='fs-label'; wrap.appendChild(label);
    const cells=[];
    for(let i=0;i<den;i++){ const c=document.createElement('div'); c.className='fs-cell'; fig.appendChild(c); cells.push(c); }
    stage.appendChild(wrap);
    step(()=>{ fig.classList.add('fs-divided'); label.textContent='Dividido en '+den+' partes iguales'; });
    for(let i=0;i<num;i++) step(()=>{ cells[i].classList.add('fs-shaded'); });
    step(()=>{ label.textContent='Tomamos '+num+' de '+den+'  →  '+num+'/'+den; label.classList.add('show'); });
  },
  // coins-add — monedas que se suman una a una con total corriente.
  'coins-add': function(stage, p, step){
    const coins=p.coins||[100,50,10,5], cur=p.currency||'$';
    const wrap=document.createElement('div'); wrap.className='ca-wrap';
    const row=document.createElement('div'); row.className='ca-coins'; wrap.appendChild(row);
    const total=document.createElement('div'); total.className='ca-total'; total.textContent=cur+'0'; wrap.appendChild(total);
    // Hallazgo 11 (Lote 5, 2026-07-20): mismo dibujo de billete/moneda que
    // renderCoins (makeMoneyVisual, definida más abajo pero disponible acá
    // por hoisting de function — Representación Idéntica 2.9) en vez del
    // rectángulo/círculo liso que tenía esta demo antes.
    const els=coins.map(c=>{ const e=makeMoneyVisual(c, cur); e.classList.add('ca-coin'); row.appendChild(e); return e; });
    stage.appendChild(wrap);
    let running=0;
    coins.forEach((c,i)=> step(()=>{ els[i].style.opacity='1'; els[i].classList.add('ca-pop'); running+=c; total.textContent=cur+running; total.classList.add('show'); }));
  },
  // borrow — anima la resta con préstamo, columna por columna (mismo patrón que 'carry').
  borrow: function(stage, p, step, after){
    const numA=p.numA!=null?p.numA:62, numB=p.numB!=null?p.numB:27;
    const n=String(numA).length;
    const a=String(numA).padStart(n,'0').split('').map(Number);
    const b=String(numB).padStart(n,'0').split('').map(Number);
    const res=new Array(n).fill(''), workingTop=a.slice();
    const borrowedHere=new Array(n).fill(false); // esta columna recibió +10 prestado
    const lentAway=new Array(n).fill(false);     // esta columna prestó 1 a la de la derecha
    let carryBorrow=0;
    for(let i=n-1;i>=0;i--){
      let top=a[i]-carryBorrow; carryBorrow=0;
      if(top<b[i]){ top+=10; borrowedHere[i]=true; carryBorrow=1; if(i>0) lentAway[i-1]=true; }
      workingTop[i]=top; res[i]=top-b[i];
    }
    const grid=document.createElement('div'); grid.className='cd-grid';
    grid.style.gridTemplateColumns='22px repeat('+n+', 36px)';
    const annotCells=[], resCells=[], aCells=[], bCells=[];
    function add(txt,cls){ const d=document.createElement('div'); d.className='cd-cell'+(cls?' '+cls:''); d.textContent=txt; grid.appendChild(d); return d; }
    add('','');
    // Fila de anotación — convención estándar de "regrouping": la columna que
    // presta muestra su dígito ORIGINAL tachado (aCells) y el valor YA REDUCIDO
    // acá arriba (chico), no un cartel genérico "−1" (ver LMD 2026-07-06,
    // hallazgo del Director comparado contra la convención real de libros de
    // texto / Khan Academy).
    for(let i=0;i<n;i++){ const c=document.createElement('div'); c.className='cd-carry'; grid.appendChild(c); annotCells.push(c); }
    add('','op'); for(let i=0;i<n;i++) aCells.push(add(String(a[i])));
    add('−','op'); for(let i=0;i<n;i++) bCells.push(add(String(b[i])));
    const line=document.createElement('div'); line.className='cd-line'; grid.appendChild(line);
    add('',''); for(let i=0;i<n;i++) resCells.push(add(''));
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.appendChild(grid); stage.appendChild(gridWrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);
    for(let i=n-1;i>=0;i--){
      const col=i, isLast=col===0;
      step(()=>{
        aCells.forEach(c=>c.classList.remove('lit')); bCells.forEach(c=>c.classList.remove('lit'));
        aCells[col].classList.add('lit'); bCells[col].classList.add('lit');
        bubble.textContent = borrowedHere[col] ? (a[col]+' − '+b[col]+': no alcanza, pido prestado → '+workingTop[col]+' − '+b[col]+' = '+res[col])
                            : lentAway[col]     ? (a[col]+' presta 1 → queda '+workingTop[col]+' − '+b[col]+' = '+res[col])
                                                 : (workingTop[col]+' − '+b[col]+' = '+res[col]);
        bubble.classList.add('show');
        after(()=>{
          resCells[col].textContent=res[col]; resCells[col].classList.add('result');
          // Columna que RECIBE el préstamo (2026-07-13, hallazgo del
          // Director): el valor regrupado (ej. 2→12) solo vivía en la
          // burbuja, nunca quedaba anotado en la grilla — se agrega acá, SIN
          // tachar (tachar es solo para quien PRESTA, más abajo). Cubre
          // también el préstamo en cadena (604-278: el 4→14) porque cada
          // columna anota su propio workingTop cuando le toca su paso.
          if(borrowedHere[col]){
            annotCells[col].textContent=String(workingTop[col]);
            annotCells[col].classList.add('show');
          }
          if(borrowedHere[col] && col>0){
            const lender=col-1;
            aCells[lender].classList.add('struck');
            annotCells[lender].textContent=String(workingTop[lender]);
            annotCells[lender].classList.add('show');
          }
          if(isLast) after(()=>{
            bubble.classList.remove('show');
            aCells.forEach(c=>c.classList.remove('lit')); bCells.forEach(c=>c.classList.remove('lit'));
            resCells.forEach(c=>{ if(c.textContent!=='') c.classList.add('lit'); });
          }, 300);
        }, 520);
      });
    }
  },
  // mult-carry — anima la multiplicación por 1 dígito, con acarreo (mismo patrón que 'carry').
  'mult-carry': function(stage, p, step, after){
    const numA=p.numA!=null?p.numA:458, factor=p.numB!=null?p.numB:6;
    const aDigits=String(numA).split('').map(Number);
    const n=aDigits.length;
    const res=new Array(n+1).fill('');
    let carry=0;
    const prods=[];
    for(let i=n-1;i>=0;i--){
      const prod=aDigits[i]*factor+carry;
      const digit=prod%10; carry=Math.floor(prod/10);
      res[i+1]=digit; prods[i]={digit, carry, raw:aDigits[i]*factor};
      if(carry>0 && i===0) res[0]=carry;
    }
    const grid=document.createElement('div'); grid.className='cd-grid';
    grid.style.gridTemplateColumns='22px repeat('+(n+1)+', 36px)';
    const carryCells=[], resCells=[], aCells=[];
    function add(txt,cls){ const d=document.createElement('div'); d.className='cd-cell'+(cls?' '+cls:''); d.textContent=txt; grid.appendChild(d); return d; }
    add('','');
    for(let i=0;i<n+1;i++){ const c=document.createElement('div'); c.className='cd-carry'; grid.appendChild(c); carryCells.push(c); }
    add('','op'); add(''); for(let i=0;i<n;i++) aCells.push(add(String(aDigits[i])));
    add('×','op'); add(''); for(let i=0;i<n-1;i++) add(''); add(String(factor));
    const line=document.createElement('div'); line.className='cd-line'; grid.appendChild(line);
    add('',''); for(let i=0;i<n+1;i++) resCells.push(add(''));
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.appendChild(grid); stage.appendChild(gridWrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);
    const hasExtraDigit = res[0]!=='';
    function cleanup(){
      bubble.classList.remove('show');
      aCells.forEach(c=>c.classList.remove('lit'));
      resCells.forEach(c=>{ if(c.textContent!=='') c.classList.add('lit'); });
    }
    for(let i=n-1;i>=0;i--){
      const col=i, {digit, carry:carryOut, raw}=prods[i];
      const carryIn = i<n-1 ? prods[i+1].carry : 0;
      const isLast = col===0 && !hasExtraDigit;
      step(()=>{
        aCells.forEach(c=>c.classList.remove('lit'));
        aCells[col].classList.add('lit');
        bubble.textContent = aDigits[col]+' × '+factor+(carryIn>0?' + '+carryIn:'')+' = '+(raw+carryIn);
        bubble.classList.add('show');
        after(()=>{
          resCells[col+1].textContent=digit; resCells[col+1].classList.add('result');
          if(carryOut>0){ carryCells[col].textContent=String(carryOut); carryCells[col].classList.add('show'); }
          if(isLast) after(cleanup, 300);
        }, 520);
      });
    }
    if(hasExtraDigit){
      step(()=>{
        resCells[0].textContent=res[0]; resCells[0].classList.add('result');
        after(cleanup, 300);
      });
    }
  },
  // mult-partial — multiplicación de 2+ cifras. Reescrita 2026-07-14 (item
  // 3.2, Representación Idéntica / 2.9): antes mostraba 3 líneas de texto
  // ("24×3=72", "24×10=240", "312"), una representación distinta de la
  // grilla en columnas que exige la práctica calificada (renderMultColumns,
  // .multc-grid). Ahora usa la MISMA grilla — multiplicando, multiplicador,
  // una fila de producto parcial por dígito (con llevada) desplazada a la
  // izquierda, y la suma final — mismo algoritmo de columnas que
  // renderMultColumns, solo de solo-lectura y revelado paso a paso.
  'mult-partial': function(stage, p, step, after){
    const numA=p.numA!=null?p.numA:24, numB=p.numB!=null?p.numB:13;
    const aDigits=String(numA).split('').map(Number), n=aDigits.length;
    const bDigits=String(numB).split('').map(Number), m=bDigits.length;
    const GRID_TOTAL=n+m+2;
    function gc(c){ return GRID_TOTAL+1-c; }

    const grid=document.createElement('div'); grid.className='multc-grid';
    grid.style.gridTemplateColumns=`repeat(${GRID_TOTAL+1}, var(--multc-col-w))`;
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.appendChild(grid);
    stage.appendChild(gridWrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);

    let rowCounter=0;
    function nextRow(){ return ++rowCounter; }
    function mkCell(text,cls,col,row){
      const d=document.createElement('div'); d.className='multc-cell'+(cls?' '+cls:'');
      d.textContent=text; d.style.gridColumn=col; d.style.gridRow=row;
      grid.appendChild(d); return d;
    }

    const headRow=nextRow();
    const aCells=[];
    aDigits.forEach((d,i)=>{ const c=n-1-i; aCells[c]=mkCell(d,null,gc(c),headRow); });

    const factorRow=nextRow();
    mkCell('×','sign',1,factorRow);
    const bCells=[];
    bDigits.forEach((d,i)=>{ const c=m-1-i; bCells[c]=mkCell(d,'dim',gc(c),factorRow); });

    const lineRow=nextRow();
    const line=document.createElement('div'); line.className='multc-line-row';
    line.style.gridColumn=`2 / ${GRID_TOTAL+2}`; line.style.gridRow=lineRow;
    grid.appendChild(line);

    // Mismo algoritmo de precálculo que renderMultColumns: una fila parcial
    // por dígito del multiplicador (de derecha a izq.), desplazada k lugares.
    const partials=bDigits.slice().reverse().map((factorDigit,k)=>{
      const productDigitAt={}, carryOutAt={};
      let running=0;
      for(let i=0;i<n;i++){
        const dA=aDigits[n-1-i];
        const raw=dA*factorDigit+running;
        const colAbs=i+k;
        productDigitAt[colAbs]=raw%10;
        running=Math.floor(raw/10);
        carryOutAt[colAbs]=running;
      }
      const finalCarryCol=n+k;
      if(running>0) productDigitAt[finalCarryCol]=running;
      return {factorDigit, offset:k, productDigitAt, carryOutAt};
    });

    function clearLit(){ aCells.forEach(c=>c&&c.classList.remove('lit')); bCells.forEach(c=>c&&c.classList.remove('lit')); }
    function cleanup(){ bubble.classList.remove('show'); clearLit(); }

    const partialMaxCols=[]; // max col usado por cada fila parcial, para la línea de suma
    partials.forEach((part,k)=>{
      const carryRow=nextRow();
      const prodRow=nextRow();
      const cols=Object.keys(part.productDigitAt).map(Number).sort((a,b)=>a-b);
      const minC=cols[0], maxC=cols[cols.length-1];
      partialMaxCols.push(maxC);
      const carryCells={};
      for(let c=minC+1;c<=maxC;c++) carryCells[c]=mkCell('','carry',gc(c),carryRow);
      const prodCells={};
      cols.forEach(c=>{ prodCells[c]=mkCell('',null,gc(c),prodRow); });

      cols.forEach((c,idx)=>{
        const isLastCol=(idx===cols.length-1);
        const isLastPartial=(k===partials.length-1);
        const isVeryLast=isLastCol && isLastPartial && m===1; // sin fila de suma si el multiplicador es de 1 cifra
        const carryIn = idx>0 ? (part.carryOutAt[cols[idx-1]]||0) : 0;
        const posInA=c-part.offset;
        const dA=posInA<n ? aDigits[n-1-posInA] : null;
        step(()=>{
          clearLit();
          if(dA!=null && aCells[posInA]) aCells[posInA].classList.add('lit');
          if(bCells[part.offset]) bCells[part.offset].classList.add('lit');
          bubble.textContent = dA!=null
            ? (dA+' × '+part.factorDigit+(carryIn>0?' + '+carryIn:'')+' = '+(dA*part.factorDigit+carryIn))
            : String(carryIn);
          bubble.classList.add('show');
          after(()=>{
            prodCells[c].textContent=part.productDigitAt[c];
            prodCells[c].classList.add('result');
            const carryOut=part.carryOutAt[c]||0;
            if(carryOut>0 && carryCells[c+1]){ carryCells[c+1].textContent=String(carryOut); carryCells[c+1].classList.add('show'); }
            if(isVeryLast) after(cleanup, 300);
          }, 520);
        });
      });
    });

    // Fila de suma final — solo si el multiplicador tiene 2+ cifras (si no,
    // la única fila parcial YA es el resultado, como en DEMOS['mult-carry']).
    if(m>1){
      const overallMax=Math.max(...partialMaxCols);
      const signRow=nextRow();
      mkCell('+','sign',1,signRow);
      const lineRow2=nextRow();
      const line2=document.createElement('div'); line2.className='multc-line-row';
      line2.style.gridColumn=`${gc(overallMax+1)} / ${GRID_TOTAL+2}`; line2.style.gridRow=lineRow2;
      grid.appendChild(line2);
      const sumRow=nextRow();
      const total=numA*numB;
      const totalDigits=String(total).split('').reverse();
      step(()=>{
        clearLit();
        bubble.textContent='Sumamos los productos parciales';
        bubble.classList.add('show');
        after(()=>{
          totalDigits.forEach((d,c)=>{ mkCell(d,'result',gc(c),sumRow); });
          after(cleanup, 300);
        }, 520);
      });
    }
  },
  // div-steps — anima la división larga con la MISMA casita/bracket que
  // renderDivLarga (el ejercicio real que el alumno practica después) —
  // corregido 2026-07-07: la versión anterior mostraba una lista de
  // ecuaciones verbales ("43÷6=7, sobran 1"), una representación distinta
  // de la que ve en el ejercicio calificado (hallazgo del Director,
  // auditoría visual de demos). Mismo algoritmo de renderDivLarga
  // (dígito por dígito, saltando el dígito líder que no alcanza), sin
  // inputs — solo revela el resultado ya calculado, paso a paso.
  'div-steps': function(stage, p, step, after){
    const dividendo=p.dividendo!=null?p.dividendo:438, divisor=p.divisor!=null?p.divisor:6;
    const dividendDigits=String(dividendo).split('').map(Number);
    const steps=[]; let carry=0, started=false, pendingDigitIndices=[];
    for(let i=0;i<dividendDigits.length;i++){
      const digit=dividendDigits[i];
      pendingDigitIndices.push(i);
      const working=carry*10+digit;
      const qDigit=Math.floor(working/divisor);
      const product=qDigit*divisor;
      const remainder=working-product;
      const isLeading=!started && qDigit===0 && i<dividendDigits.length-1;
      if(!isLeading) started=true;
      steps.push({usedDigitIndices:[...pendingDigitIndices], workingNumber:working, quotientDigit:qDigit, product, remainder, skipped:isLeading});
      if(!isLeading) pendingDigitIndices=[];
      carry=remainder;
    }
    const finalRemainder=carry;

    const wrap=document.createElement('div'); wrap.className='divl-wrap';
    wrap.innerHTML=`
      <div class="divl-head-row">
        <div class="divl-dividend-row" id="ds-dividend-row"></div>
        <div class="divl-head-bracket">
          <div class="divl-head-corner">${divisor}</div>
          <div class="divl-quotient-zone" id="ds-quotient-zone"></div>
        </div>
      </div>
      <div id="ds-steps"></div>`;
    stage.appendChild(wrap);
    const dividendRow=wrap.querySelector('#ds-dividend-row');
    const quotientZone=wrap.querySelector('#ds-quotient-zone');
    const stepsBox=wrap.querySelector('#ds-steps');
    const dividendCells=dividendDigits.map(d=>{
      const cell=document.createElement('div'); cell.className='divl-dividend-digit'; cell.textContent=d;
      dividendRow.appendChild(cell); return cell;
    });

    function cleanup(){
      const fr=document.createElement('div'); fr.className='divl-final-rest';
      fr.innerHTML = finalRemainder>0 ? `Resto: <span class="val">${finalRemainder}</span>` : `División exacta`;
      wrap.appendChild(fr);
    }
    const realSteps = steps.filter(s=>!s.skipped);
    steps.forEach(dstep=>{
      if(dstep.skipped){
        // Mismo comportamiento que renderDivLarga: el dígito líder que no
        // alcanza se marca y se funde con el próximo paso, sin cociente propio.
        step(()=>{ dstep.usedDigitIndices.forEach(i=>dividendCells[i].classList.add('used-now')); });
        return;
      }
      const isLast = dstep===realSteps[realSteps.length-1];

      // Misma resta que antes — ahora extraída para poder revelarse en su
      // propio paso cuando hay comprobación de por medio (divisor>=10). Si
      // ya existe un stepDiv (el de la comprobación), la resta se agrega ahí
      // mismo — mismo "card" de paso que el ejercicio calificado.
      function revealSubtraction(existingStepDiv){
        const numCols=String(dstep.workingNumber).length;
        const productDigits=String(dstep.product).padStart(numCols,' ').split('');
        const restRow=document.createElement('div'); restRow.className='divl-restcol-row';
        const sign=document.createElement('div'); sign.className='divl-restcol-sign'; sign.textContent='−';
        restRow.appendChild(sign);
        productDigits.forEach(ch=>{
          const d=document.createElement('div');
          d.className = ch.trim()===''? 'divl-restcol-digit' : 'divl-rest-input correct';
          d.textContent = ch.trim();
          restRow.appendChild(d);
        });
        const line=document.createElement('div'); line.className='divl-restcol-line'; line.style.width=(numCols*36+20)+'px';
        const remRow=document.createElement('div'); remRow.className='divl-restcol-row';
        for(let i=0;i<numCols-1;i++){ const blank=document.createElement('div'); blank.className='divl-restcol-digit'; remRow.appendChild(blank); }
        const remCell=document.createElement('div'); remCell.className='divl-rest-input correct'; remCell.textContent=dstep.remainder;
        remRow.appendChild(remCell);

        const restcol=document.createElement('div'); restcol.className='divl-restcol';
        const lastUsedIdx=dstep.usedDigitIndices[dstep.usedDigitIndices.length-1];
        restcol.style.marginLeft=((lastUsedIdx-numCols+1)*34)+'px';
        restcol.appendChild(restRow); restcol.appendChild(line); restcol.appendChild(remRow);

        const stepDiv=existingStepDiv || document.createElement('div');
        if(!existingStepDiv){ stepDiv.className='divl-step'; stepDiv.style.opacity='0'; stepsBox.appendChild(stepDiv); }
        stepDiv.appendChild(restcol);
        requestAnimationFrame(()=>{ stepDiv.style.opacity='1'; stepDiv.classList.add('nb-pop'); });

        dstep.usedDigitIndices.forEach(i=>{ dividendCells[i].classList.remove('used-now'); dividendCells[i].classList.add('used-past'); });
        if(isLast) after(cleanup, 300);
      }

      let verifyStepDiv=null;
      step(()=>{
        dstep.usedDigitIndices.forEach(i=>dividendCells[i].classList.add('used-now'));
        after(()=>{
          const qd=document.createElement('div'); qd.className='divl-quotient-input correct'; qd.textContent=dstep.quotientDigit;
          quotientZone.appendChild(qd);
          // Comprobación de la multiplicación (item 4.1/EJ-000068, 2026-07-14
          // — Representación Idéntica / 2.9): con divisor de 2+ cifras el
          // ejercicio calificado (afterQuotientCorrect/showVerifyStep) nunca
          // resta sin mostrar antes DE DÓNDE sale el número — acá tampoco.
          // Gateado por divisor>=10: el caso de 1 cifra (renderDivLarga con
          // el demo original, 438÷6) sigue exactamente igual.
          if(divisor>=10){
            verifyStepDiv=document.createElement('div'); verifyStepDiv.className='divl-step'; verifyStepDiv.style.opacity='0';
            const vRow=document.createElement('div'); vRow.className='divl-verify-row';
            const eq=document.createElement('span'); eq.className='divl-verify-eq'; eq.textContent=`${divisor} × ${dstep.quotientDigit} = `;
            const ans=document.createElement('span'); ans.className='divl-verify-input correct'; ans.textContent=dstep.product;
            vRow.appendChild(eq); vRow.appendChild(ans);
            verifyStepDiv.appendChild(vRow);
            stepsBox.appendChild(verifyStepDiv);
            requestAnimationFrame(()=>{ verifyStepDiv.style.opacity='1'; verifyStepDiv.classList.add('nb-pop'); });
          } else {
            revealSubtraction();
          }
        }, 520);
      });

      if(divisor>=10){
        step(()=>{ after(()=>revealSubtraction(verifyStepDiv), 520); });
      }
    });
  },
  // clock-hour — leer la hora: resalta primero la aguja corta (hora), después
  // la larga (minutos). Mismo dibujo SVG que renderClock (item 4.1, Fase 4).
  'clock-hour': function(stage, p, step, after){
    const hours=p.hours!=null?p.hours:3, minutes=p.minutes!=null?p.minutes:30;
    const wrap=document.createElement('div'); wrap.className='clk-wrap';
    const {hHand, mHand}=buildClockFace(wrap, hours, minutes);
    const resultEl=document.createElement('div'); resultEl.className='clk-demo-result'; wrap.appendChild(resultEl);
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.style.position='relative';
    gridWrap.appendChild(wrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);
    stage.appendChild(gridWrap);
    const displayH=(hours%12)||12, displayM=minutes||0;
    function cleanup(){ bubble.classList.remove('show'); hHand.classList.remove('active'); mHand.classList.remove('active'); }
    step(()=>{
      hHand.classList.add('active'); mHand.classList.remove('active');
      bubble.textContent='La aguja corta marca la hora. Fijate dónde está.';
      bubble.classList.add('show');
      after(()=>{
        resultEl.textContent='Son las '+displayH+' y algo';
        resultEl.classList.add('show');
      }, 520);
    });
    step(()=>{
      hHand.classList.remove('active'); mHand.classList.add('active');
      bubble.textContent='La aguja larga marca los minutos. Cada número vale 5: '+(displayM/5)+' × 5 = '+displayM+'.';
      bubble.classList.add('show');
      after(()=>{
        resultEl.textContent=displayH+':'+String(displayM).padStart(2,'0');
        after(cleanup, 300);
      }, 520);
    });
  },
  // clock-minutes — el foco es SOLO la aguja larga (minutos): cuenta de a 5
  // primero, recién después combina con la hora. Mismo dibujo que clock-hour
  // (reusa buildClockFace) pero orden y foco distintos — habilidad atómica
  // separada (decisión del Director, 2026-07-14: no combinar en un solo demo).
  'clock-minutes': function(stage, p, step, after){
    const hours=p.hours!=null?p.hours:3, minutes=p.minutes!=null?p.minutes:30;
    const wrap=document.createElement('div'); wrap.className='clk-wrap';
    const {hHand, mHand}=buildClockFace(wrap, hours, minutes);
    const resultEl=document.createElement('div'); resultEl.className='clk-demo-result'; wrap.appendChild(resultEl);
    const gridWrap=document.createElement('div'); gridWrap.className='cd-gridwrap'; gridWrap.style.position='relative';
    gridWrap.appendChild(wrap);
    const bubble=document.createElement('div'); bubble.className='cd-bubble'; gridWrap.appendChild(bubble);
    stage.appendChild(gridWrap);
    const displayH=(hours%12)||12, displayM=minutes||0;
    const num=Math.round(displayM/5);
    function cleanup(){ bubble.classList.remove('show'); hHand.classList.remove('active'); mHand.classList.remove('active'); }
    step(()=>{
      mHand.classList.add('active'); hHand.classList.remove('active');
      bubble.textContent='La aguja larga está en el '+num+'. Cada número vale 5 minutos.';
      bubble.classList.add('show');
      after(()=>{
        resultEl.textContent=num+' × 5 = '+displayM+' minutos';
        resultEl.classList.add('show');
      }, 520);
    });
    step(()=>{
      hHand.classList.add('active');
      bubble.textContent='Juntamos con la hora, que ya sabemos que es '+displayH+'.';
      bubble.classList.add('show');
      after(()=>{
        resultEl.textContent=displayH+':'+String(displayM).padStart(2,'0');
        after(cleanup, 300);
      }, 520);
    });
  }
};

// LAYOUT 'columnas': suma apilada con llevadas visibles (misma lógica que DEMOS.carry).
function renderColumnSum(a, b){
  const A=String(a), B=String(b), n=Math.max(A.length,B.length)+1;
  const ad=A.padStart(n,' ').split(''), bd=B.padStart(n,' ').split('');
  const res=new Array(n).fill(''), carries=new Array(n).fill(''); let carry=0;
  for(let i=n-1;i>=0;i--){
    const da=ad[i]===' '?0:+ad[i], db=bd[i]===' '?0:+bd[i];
    if(ad[i]===' '&&bd[i]===' '&&carry===0) continue;
    const s=da+db+carry; res[i]=String(s%10); carry=Math.floor(s/10);
    if(carry>0&&i>0) carries[i-1]=String(carry);
  }
  const grid=document.createElement('div');
  grid.style.cssText='display:inline-grid;grid-template-columns:24px repeat('+n+',32px);gap:2px;justify-content:center;margin:4px 0 10px;';
  const cell=(txt,css)=>{ const d=document.createElement('div'); d.textContent=txt; d.style.cssText='display:flex;align-items:center;justify-content:center;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:22px;'+(css||''); return d; };
  grid.appendChild(cell(''));
  for(let i=0;i<n;i++) grid.appendChild(cell(carries[i],'font-size:13px;height:18px;color:var(--color-primary);font-weight:700;'));
  grid.appendChild(cell(''));
  for(let i=0;i<n;i++) grid.appendChild(cell(ad[i]===' '?'':ad[i]));
  grid.appendChild(cell('+','color:var(--text-muted);'));
  for(let i=0;i<n;i++) grid.appendChild(cell(bd[i]===' '?'':bd[i]));
  const line=document.createElement('div'); line.style.cssText='grid-column:1 / span '+(n+1)+';border-top:2px solid var(--text-strong, currentColor);margin:2px 0;'; grid.appendChild(line);
  grid.appendChild(cell(''));
  for(let i=0;i<n;i++) grid.appendChild(cell(res[i],'color:var(--color-primary);font-weight:700;'));
  return grid;
}

// Modo de apoyo (Fase 5, item 5.3, 2026-07-20): recurso de referencia fijo,
// no ligado al ejercicio actual — a diferencia de showHelp/closeHelp (Nivel 4,
// ayuda contextual de ESTE ejercicio). Overlay propio, mismo patrón visual.
function buildTimesTableHtml(){
  let h='<div class="support-times-table-wrap"><table class="support-times-table"><thead><tr><th>×</th>';
  for(let c=1;c<=10;c++) h+='<th>'+c+'</th>';
  h+='</tr></thead><tbody>';
  for(let r=1;r<=10;r++){
    h+='<tr><th>'+r+'</th>';
    for(let c=1;c<=10;c++) h+='<td>'+(r*c)+'</td>';
    h+='</tr>';
  }
  h+='</tbody></table></div>';
  return h;
}

// MATH_PLUGIN fase 4 (plan post-lote, 2026-07-22): regla extra de
// validación, antes inline dentro de validateExercise(). Pizarra
// suma/resta (place-value, 2026-07-12): si declara operation, exige
// numA/numB numéricos.
MATH_PLUGIN.validateExtra = function(ex, errors){
  if (ex.kind === 'place-value' && ex.operation) {
    if (ex.operation !== 'add' && ex.operation !== 'subtract') errors.push('place-value: operation debe ser "add" o "subtract"');
    if (typeof ex.numA !== 'number' || typeof ex.numB !== 'number') errors.push('place-value: operation declarada sin numA/numB numéricos');
  }
  // MAT-21, Gate de Motor (2026-08-03): frac-visual mode:'compare'/'equivalent'
  // — extensión aditiva, no toca shade/identify (sin `mode` o mode:'shade'/'identify').
  if (ex.kind === 'frac-visual' && (ex.mode === 'compare' || ex.mode === 'equivalent')) {
    if (typeof ex.numerator2 !== 'number' || typeof ex.denominator2 !== 'number')
      errors.push(`frac-visual mode:'${ex.mode}': numerator2/denominator2 numéricos obligatorios`);
    if (ex.mode === 'compare' && !['<','>','='].includes(ex.answer))
      errors.push("frac-visual mode:'compare': answer debe ser '<', '>' o '='");
    if (ex.mode === 'equivalent' && typeof ex.answer !== 'boolean')
      errors.push("frac-visual mode:'equivalent': answer debe ser boolean");
  }
  // MAT-02, Gate de Motor (2026-08-03): count-objects — items 1-10, icon un solo
  // emoji, layout/mode de un set cerrado, target/answer condicionales al mode
  // (no puede vivir en KIND_SPECS.rules porque depende de qué mode se declaró).
  if (ex.kind === 'count-objects') {
    if (typeof ex.items !== 'number' || ex.items < 1 || ex.items > 10)
      errors.push('count-objects: items debe ser un número entre 1 y 10');
    if (!ex.icon) errors.push('count-objects: falta icon');
    if (!['row','scatter','ten-frame'].includes(ex.layout))
      errors.push("count-objects: layout debe ser 'row', 'scatter' o 'ten-frame'");
    if (!['tap-count','match-target'].includes(ex.mode))
      errors.push("count-objects: mode debe ser 'tap-count' o 'match-target'");
    if (ex.mode === 'tap-count' && typeof ex.answer !== 'number')
      errors.push("count-objects mode:'tap-count': answer numérico obligatorio");
    if (ex.mode === 'match-target' && typeof ex.target !== 'number')
      errors.push("count-objects mode:'match-target': target numérico obligatorio");
  }
};
// MATH_PLUGIN fase 5 (plan post-lote, 2026-07-22): gate del botón de
// apoyo (tabla pitagórica, Fase 5 ítem 5.3, 2026-07-20), antes inline
// en renderExercise().
MATH_PLUGIN.showsSupport = function(kind){
  return ['mult-columns','div-larga'].includes(kind);
};
// MATH_PLUGIN fase 6 (plan post-lote, 2026-07-22): reset de banderas
// por-kind, antes un bloque de 12 líneas en renderExercise() que
// reseteaba las 22 banderas de los 12 kinds SIEMPRE, sin importar cuál
// es el ejercicio actual. Solo las banderas (Familia A del mapa de
// dependencias) — los campos "de datos" (Familia B: *ResultInputs,
// *Expected, *InputQueue, etc.) nunca estuvieron en este bloque, cada
// renderer los sobreescribe al entrar, así que no cambian acá.
MATH_PLUGIN.resetState = function(kind){
  switch(kind){
    case 'sum-columns':    state.sumColHadError=false; state.sumColDone=false; break;
    case 'rest-columns':   state.restColHadError=false; state.restColDone=false; break;
    case 'div-larga':      state.divlHadError=false; state.divlDone=false; break;
    case 'mult-columns':   state.multcHadError=false; state.multcDone=false; break;
    case 'frac-visual':    state.fracvDone=false; state.fracvHadError=false; break;
    case 'number-line':    state.nlHadError=false; break;
    case 'frac-steps':     state.frsHadError=false; state.frsAllDone=false; break;
    case 'number-sequence':state.nseqHadError=false; break;
    case 'place-value':    state.pvHadError=false; state.pvDone=false; break;
    case 'clock':          state.clkHadError=false; state.clkDone=false; break;
    case 'eq-missing':     state.eqmHadError=false; break;
    case 'eq-linear':      state.eqlHadError=false; state.eqlDone=false; break;
    case 'count-objects':  state.coHadError=false; state.coTapped=null; state.coSelected=null; state.coConfirmInput=null; break;
  }
};
// MATH_PLUGIN fase 11 (plan post-lote, 2026-07-22): antes un ternario
// anidado de 12 niveles en handleConfirm() (usedHintOrError), mapeando
// kind → flag *HadError, con fallback a state.usedHintThisEx para todo
// kind sin flag propio (coins, eq-balance, y los no-matemáticos).
// Lógica idéntica, solo reestructurada a switch (mismo criterio que
// resetState arriba).
MATH_PLUGIN.getHadError = function(kind){
  switch(kind){
    case 'sum-columns':     return state.sumColHadError;
    case 'rest-columns':    return state.restColHadError;
    case 'div-larga':       return state.divlHadError;
    case 'mult-columns':    return state.multcHadError;
    case 'frac-visual':     return state.fracvHadError;
    case 'number-line':     return state.nlHadError;
    case 'frac-steps':      return state.frsHadError;
    case 'number-sequence': return state.nseqHadError;
    case 'place-value':     return state.pvHadError;
    case 'clock':           return state.clkHadError;
    case 'eq-missing':      return state.eqmHadError;
    case 'eq-linear':       return state.eqlHadError;
    case 'count-objects':   return state.coHadError;
    default:                return state.usedHintThisEx;
  }
};
// MATH_PLUGIN fase 12 (plan post-lote, 2026-07-22, última fase): antes
// dos bloques if inline en handleConfirm(), con nombres de kind
// adentro — el mismo tipo de fuga F1-F3 que las fases anteriores ya
// venían saldando. Lógica idéntica, solo movida: marca en fucsia
// (--celebrate, vía la clase .final-correct que ya trae el CSS del
// Lote Director 2026-07-22) SOLO la celda de resultado final de las
// grillas multi-paso al Confirmar correcto — los pasos intermedios
// quedan verdes, sin cambios.
MATH_PLUGIN.markFinalCorrect = function(ex, isCorrect){
  if(!isCorrect) return;
  if(['sum-columns','rest-columns','mult-columns','div-larga'].includes(ex.kind)){
    let finalCells = [];
    if(ex.kind==='sum-columns') finalCells = state.sumColResultInputs||[];
    else if(ex.kind==='rest-columns') finalCells = state.restColResultInputs||[];
    else if(ex.kind==='mult-columns') finalCells = (state.multcResultInputs||[]).map(item=>item.inp);
    else if(ex.kind==='div-larga') finalCells = [].slice.call(document.querySelectorAll('#exercise-input-area .divl-quotient-input'));
    finalCells.forEach(inp=>{ if(inp && inp.classList.contains('correct')) inp.classList.add('final-correct'); });
  } else if(ex.kind==='frac-steps'){
    const frs = [].slice.call(document.querySelectorAll('#exercise-input-area .frs-inp.correct'));
    if(frs.length) frs[frs.length-1].classList.add('final-correct');
  }
};
// MATH_PLUGIN fase 7 (plan post-lote, 2026-07-22): dispatcher de
// renderers, antes 14 ramas else-if directas en renderExercise(). El
// caso 'sum-columns' conserva el gate de freeAttempt (Fase 5, item 5.4,
// 2026-07-20 — decisión del Director): un freeAttempt marcado por error
// en evaluación NUNCA activa el modo libre, cae al sum-columns normal
// (gateado, autocorregido, 1 intento). Evaluación mide; freeAttempt
// enseña — no pueden convivir aunque el contenido se equivoque.
MATH_PLUGIN.renderers = {
  'sum-columns': function(ex, area){
    if (ex.freeAttempt && !isEvalModule(state.currentModule)) renderSumColumnsFree(ex,area);
    else renderSumColumns(ex,area);
  },
  'rest-columns':    renderRestColumns,
  'div-larga':       renderDivLarga,
  'mult-columns':    renderMultColumns,
  'frac-visual':     renderFracVisual,
  'number-line':     renderNumberLine,
  'frac-steps':      renderFracSteps,
  'eq-balance':      renderEqBalance,
  'number-sequence': renderNumberSequence,
  'place-value':     renderPlaceValue,
  'clock':           renderClock,
  'coins':           renderCoins,
  'eq-missing':      renderEqMissing,
  'eq-linear':       renderEqLinear,
  'count-objects':   renderCountObjects,
};
// MATH_PLUGIN fase 8 (plan post-lote, 2026-07-22): antes 3 ramas
// inline en doReveal(). Comentario OA-011 migrado tal cual (instrucción
// explícita del plan) — 'sum-columns' NUNCA llega acá — su "Revelar"
// usa state.revealFn (revela todas las columnas de una vez), no
// activeReveal. Vestigio de que alguna vez fue progresivo como sus 3
// hermanos — código muerto real, confirmado y registrado como
// incidente OA-011 (2026-07-14) en vez de borrado silencioso.
MATH_PLUGIN.onReveal = function(kind){
  if(kind==='mult-columns')    state.multcHadError=true;
  else if(kind==='div-larga')  state.divlHadError=true;
  else if(kind==='rest-columns')state.restColHadError=true;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22): cadena principal de
// corrección, antes 14 ramas else-if inline en handleConfirm(). Mayor
// riesgo de las 12 fases — toca la corrección de los 215 ejercicios
// certificados. UN COMMIT POR KIND, batería completa después de cada
// uno (instrucción explícita de Dirección). ctx = {isEval, isEvalCorrect}
// — isEvalCorrect es la misma función closure de handleConfirm, pasada
// tal cual para no reimplementarla acá.
// Renombrado de _checkers a checkers (Prompt 10, 2026-09-08): el Core
// necesitaba consultar "¿existe corrección para este kind?" antes de
// despachar (mismo patrón que ya usa MATH_PLUGIN.renderers, público, sin
// guion bajo) — mantenerlo privado hubiera obligado al Core a asomarse a
// un detalle interno del plugin. Renombre puro, ningún comportamiento
// cambió.
MATH_PLUGIN.checkers = {};
MATH_PLUGIN.checkCorrect = function(kind, ex, ctx){
  return MATH_PLUGIN.checkers[kind](ex, ctx);
};
MATH_PLUGIN.checkers['sum-columns'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // freeAttempt (Fase 5, item 5.4, 2026-07-20): el dispatcher de render
  // ya garantiza que esto solo es true fuera de evaluación (gate B) — acá
  // no hace falta repetir el chequeo, pero sí excluir isEval por claridad.
  // Reusa TAL CUAL la fórmula de Fix B.2 (releer valor final de cada
  // input contra el total correcto), sin exigir sumColDone porque ese
  // flag es del modo reactivo — acá "todo lleno" ya lo garantizó
  // checkAllFilled() antes de habilitar Confirmar.
  if(ex.freeAttempt && !isEval){
    const resInps = state.sumColResultInputs || [];
    const totalPadded = String(ex.numA + ex.numB).padStart(resInps.length, '0');
    const carryInps = [].slice.call(document.querySelectorAll('#exercise-input-area .sumcol-carry-input'));
    const resultsOk = resInps.length>0 && resInps.every((inp,i) => (inp.value||'').trim() === totalPadded[i]);
    const carryOk = carryInps.every(c => (c.value||'').trim()==='1');
    isCorrect = resultsOk && carryOk;
    // Recién ACÁ se corrige — ningún input tuvo color durante el intento
    // libre: todo junto, de una, después de que el alumno terminó la
    // cuenta entera por su cuenta (a diferencia del modo gateado, que
    // corrige columna por columna en tiempo real).
    resInps.forEach((inp,i) => { inp.disabled=true; inp.classList.add((inp.value||'').trim()===totalPadded[i] ? 'correct':'wrong'); });
    carryInps.forEach(c => { c.disabled=true; c.classList.add((c.value||'').trim()==='1' ? 'correct':'wrong'); });
    // Productive Failure (Kapur 2014): la instrucción llega DESPUÉS del
    // intento fallido completo, no antes. NO se llama requestHelp() acá a
    // propósito — el cierre común de handleConfirm (más abajo, "Reacción
    // al error") YA abre el Nivel 1 solo si quedó mal y queda ayuda sin
    // mostrar; llamarlo acá también duplicaba la revelación (helpLevel
    // saltaba 0→2 en vez de 0→1) — bug propio encontrado probando antes
    // de reportar.
    if(!isCorrect) state.sumColHadError = true;
  // Fix B.2 (2026-07-20): en evaluación los campos quedan editables hasta
  // Confirmar — se relee el dígito FINAL de cada columna (y cada llevada)
  // contra el valor matemáticamente correcto, en vez de sumColHadError
  // acumulado durante el tipeo (que con reedición ya no es fiable).
  } else if(isEval){
    const resInps = state.sumColResultInputs || [];
    const totalPadded = String(ex.numA + ex.numB).padStart(resInps.length, '0');
    const resultsOk = resInps.length>0 && resInps.every((inp,i) => (inp.value||'').trim() === totalPadded[i]);
    const carryOk = [].slice.call(document.querySelectorAll('#exercise-input-area .sumcol-carry-input')).every(c => (c.value||'').trim()==='1');
    isCorrect = state.sumColDone===true && resultsOk && carryOk;
  } else {
    isCorrect = isEvalCorrect(state.sumColDone, state.sumColHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 11/14: coins.
// Lógica idéntica, solo movida. No usa isEval — misma corrección en
// práctica y evaluación. Muta el DOM directamente (clases, valor
// revelado en error) como efecto colateral, igual que el original.
MATH_PLUGIN.checkers['coins'] = function(ex, ctx){
  let isCorrect = false;
  const inp=document.querySelector('#exercise-input-area .text-input');
  if(inp){
    const expected=(ex.total!==undefined)?ex.total:ex.coins.reduce((s,c)=>s+c,0);
    const val=parseFloat(inp.value);
    isCorrect=!isNaN(val)&&Math.abs(val-expected)<0.001;
    inp.disabled=true; inp.classList.add(isCorrect?'correct':'wrong');
    if(!isCorrect) inp.value=String(expected);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 10/14: clock.
// Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['clock'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.1 (2026-07-20): en evaluación relee hora/minutos actuales del
  // DOM contra el valor esperado, en vez de clkHadError acumulado.
  if(isEval){
    const exp = state.clkExpected || {};
    const inpsClk = state.clkInputs || {};
    const hVal = parseInt(((inpsClk.inpH && inpsClk.inpH.value) || '').trim());
    const hOk = hVal===exp.h || hVal===exp.h+12;
    const mOk = exp.hoursOnly ? true : (parseInt(((inpsClk.inpM && inpsClk.inpM.value) || '').trim())===exp.m);
    isCorrect = state.clkDone===true && hOk && mOk;
  } else {
    isCorrect = isEvalCorrect(state.clkDone, state.clkHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 9/14: place-value.
// Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['place-value'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.1 (2026-07-20): mismo criterio que frac-steps/number-sequence —
  // relee el valor final de cada dígito en vez de pvHadError acumulado.
  if(isEval){
    const q = state.pvInputQueue || [];
    isCorrect = state.pvDone===true && q.every(item => parseInt((item.inp.value||'').trim())===item.expected);
  } else {
    isCorrect = isEvalCorrect(state.pvDone, state.pvHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 8/14: number-sequence.
// Lógica idéntica, solo movida. Nota real: en práctica (no isEval) es
// SIEMPRE true — no hay bug, la corrección de este kind ya ocurrió en
// vivo durante el tipeo (gate reactivo, como sum-columns no-freeAttempt);
// al llegar a Confirmar en práctica ya está garantizado correcto.
MATH_PLUGIN.checkers['number-sequence'] = function(ex, ctx){
  const isEval = ctx.isEval;
  // Fix B.1 (2026-07-20): en evaluación los campos quedan editables hasta
  // Confirmar — se relee el valor final de cada uno en vez de nseqHadError
  // acumulado (que con reedición ya no refleja el último valor tipeado).
  return isEval
    ? (state.nseqInputQueue||[]).every(item => parseInt((item.inp.value||'').trim())===item.expected)
    : true;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 7/14: frac-steps.
// Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['frac-steps'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.1 (2026-07-20): en evaluación los campos quedan editables hasta
  // Confirmar — la nota se relee del valor ACTUAL de cada input (no del
  // HadError acumulado durante el tipeo, que con reedición ya no es fiable).
  if(isEval){
    const q = state.frsInputQueue || [];
    isCorrect = state.frsAllDone===true && q.every(item => parseInt((item.inp.value||'').trim())===item.expected);
  } else {
    isCorrect = isEvalCorrect(state.frsAllDone, state.frsHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 6/14: number-line.
// Lógica idéntica, solo movida. A diferencia de los 5 anteriores, no usa
// isEval/isEvalCorrect — la corrección es la misma en práctica y
// evaluación. Muta el DOM directamente (clases, shake) como efecto
// colateral, igual que el original.
MATH_PLUGIN.checkers['number-line'] = function(ex, ctx){
  let isCorrect = false;
  if(ex.mode==='identify'){
    // identify: text input
    const inp=document.querySelector('#exercise-input-area .text-input');
    if(inp){
      const val=parseFloat(inp.value);
      isCorrect=!isNaN(val)&&Math.abs(val-ex.answer)<0.001;
      inp.disabled=true; inp.classList.add(isCorrect?'correct':'wrong');
      if(!isCorrect) inp.value=String(ex.answer);
    }
  } else {
    // place: tick click
    isCorrect=state.nlSelected!==null&&Math.abs(state.nlSelected-ex.answer)<0.001;
    if(!isCorrect){
      const body=document.getElementById('exercise-body');
      body.classList.add('anim-shake');
      setTimeout(()=>body.classList.remove('anim-shake'),400);
    }
  }
  return isCorrect;
};
// MAT-02, Gate de Motor (2026-08-03, ficha 14 MAPA_MAESTRO_INVESTIGACION_v1.md).
// tap-count: chequea el input de confirmación (cardinalidad real) Y que se haya
// tocado cada objeto exactamente una vez — no alcanza con escribir el número
// correcto sin haber contado (ver hallazgo de memoria de trabajo en discalculia,
// ficha 14: el conteo objeto-por-objeto es el mecanismo, no decoración).
// match-target: la cantidad de objetos tocados debe ser EXACTAMENTE el target.
MATH_PLUGIN.checkers['count-objects'] = function(ex, ctx){
  let isCorrect = false;
  if(ex.mode==='tap-count'){
    const inp = state.coConfirmInput;
    const val = inp ? parseInt((inp.value||'').trim()) : NaN;
    const tappedAll = state.coTapped ? state.coTapped.size===ex.items : false;
    isCorrect = !isNaN(val) && val===ex.answer && tappedAll;
    if(inp){ inp.disabled=true; inp.classList.add(isCorrect?'correct':'wrong'); if(!isCorrect) inp.value=String(ex.answer); }
  } else {
    const sel = state.coSelected || new Set();
    isCorrect = sel.size===ex.target;
    if(!isCorrect){
      const body=document.getElementById('exercise-body');
      body.classList.add('anim-shake');
      setTimeout(()=>body.classList.remove('anim-shake'),400);
    }
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 5/14: frac-visual.
// Lógica idéntica, solo movida. Nota: esta rama SÍ muta state
// (fracvHadError) además de devolver isCorrect — se preserva tal cual.
MATH_PLUGIN.checkers['frac-visual'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  if(isEval && (ex.mode||'shade')==='shade'){
    // shade: el conteo se compara con n recién al confirmar (ver onToggle) —
    // no hay HadError persistido para no penalizar toques de prueba.
    const shadedNow = document.querySelectorAll('#exercise-input-area .fracv-shaded').length;
    isCorrect = shadedNow === ex.numerator;
    if(!isCorrect) state.fracvHadError = true;
  } else {
    isCorrect = isEvalCorrect(state.fracvDone, state.fracvHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 4/14: mult-columns.
// Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['mult-columns'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.2 (2026-07-20): productos y suma final persisten en el DOM —
  // relectura fresca. Las llevadas SÍ se borran del DOM al avanzar de
  // fila (clearOldCarryInputs, mecanismo previo a Lote 1) — su corrección
  // se recuerda en multcWrongCarries (Set por referencia de elemento,
  // sobrevive a que el input se borre) en vez de releerse del DOM.
  if(isEval){
    const wrongCarries = state.multcWrongCarries || new Set();
    const prodOk = (state.multcProductInputs||[]).every(item => (item.inp.value||'').trim() === String(item.expected));
    const sumOk = (state.multcResultInputs||[]).every(item => (item.inp.value||'').trim() === String(item.expected));
    isCorrect = state.multcDone===true && wrongCarries.size===0 && prodOk && sumOk;
  } else {
    isCorrect = isEvalCorrect(state.multcDone, state.multcHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 3/14: div-larga.
// Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['div-larga'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.2 (2026-07-20): en evaluación relee el valor FINAL de cada
  // input (cociente, comprobación, producto, resto, dígito bajado) contra
  // divlExpected (poblado en cada sitio de creación), en vez de
  // divlHadError acumulado durante el tipeo.
  if(isEval){
    const expMap = state.divlExpected || {};
    const divlInps = [].slice.call(document.querySelectorAll(
      '#exercise-input-area .divl-quotient-input, #exercise-input-area .divl-verify-input, #exercise-input-area .divl-rest-input, #exercise-input-area .divl-bringdown-input'
    ));
    const allOk = divlInps.length>0 && divlInps.every(inp => {
      const exp = expMap[inp.id];
      return exp!==undefined && (inp.value||'').trim() === String(exp);
    });
    isCorrect = state.divlDone===true && allOk;
  } else {
    isCorrect = isEvalCorrect(state.divlDone, state.divlHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 2/14: rest-columns.
// Lógica idéntica, solo movida. Sin freeAttempt (no aplica a este kind).
MATH_PLUGIN.checkers['rest-columns'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect = false;
  // Fix B.2 (2026-07-20): en evaluación relee el dígito FINAL de cada
  // columna de resultado (contra la resta real ex.numA-ex.numB — la resta
  // nunca agrega columna fantasma, a diferencia de la suma) y de cada
  // préstamo (contra restColA, que ya quedó con el valor correcto
  // post-reducción), en vez de restColHadError acumulado durante el tipeo.
  if(isEval){
    const resInps = state.restColResultInputs || [];
    const numColsR = resInps.length;
    const diffPadded = String(ex.numA - ex.numB).padStart(numColsR, '0');
    const resultsOk = numColsR>0 && resInps.every((inp,i) => (inp.value||'').trim() === diffPadded[i]);
    const aArr = state.restColA || [];
    const borrowInputs = [].slice.call(document.querySelectorAll('#exercise-input-area .restcol-borrow-input'));
    const borrowOk = borrowInputs.every(inp => {
      const col = parseInt(inp.id.replace('restcol-borrow-inp-',''));
      return (inp.value||'').trim() === String(aArr[col]);
    });
    isCorrect = state.restColDone===true && resultsOk && borrowOk;
  } else {
    isCorrect = isEvalCorrect(state.restColDone, state.restColHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 12/14: eq-missing.
// Lógica idéntica, solo movida (incl. comentario Fix B.1 original).
MATH_PLUGIN.checkers['eq-missing'] = function(ex, ctx){
  const isEval = ctx.isEval, isEvalCorrect = ctx.isEvalCorrect;
  let isCorrect;
  // Fix B.1 (2026-07-20): en evaluación el campo queda editable hasta
  // Confirmar — se relee el valor ACTUAL contra eqmExpected, no la clase
  // DOM (que con Fix A no distingue correcto/incorrecto ahí) ni eqmHadError.
  if(isEval){
    const v = parseInt(((state.eqmInput && state.eqmInput.value) || '').trim());
    isCorrect = v === state.eqmExpected;
  } else {
    const answered = document.querySelector('#exercise-input-area .eqm-inp.correct, #exercise-input-area .eqm-inp.revealed') !== null;
    isCorrect = isEvalCorrect(answered, state.eqmHadError);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 13/14: eq-balance.
// Lógica idéntica, solo movida. No usa isEval/isEvalCorrect — mismo
// criterio en práctica y evaluación. Muta el DOM directamente (clases
// correct/wrong en el input y en #eqb-box, revela el valor en error).
MATH_PLUGIN.checkers['eq-balance'] = function(ex, ctx){
  let isCorrect = false;
  const inp = document.querySelector('#exercise-input-area .eqb-input');
  if(inp){
    const val = parseFloat(inp.value);
    isCorrect = !isNaN(val) && Math.abs(val-ex.answer)<0.001;
    inp.disabled = true; inp.classList.add(isCorrect?'correct':'wrong');
    const box = document.getElementById('eqb-box');
    if(box) box.classList.add(isCorrect?'correct':'wrong');
    if(!isCorrect) inp.value = String(ex.answer);
  }
  return isCorrect;
};
// MATH_PLUGIN fase 10 (plan post-lote, 2026-07-22) — 14/14: eq-linear
// (último kind, cierra checkCorrect). Lógica idéntica, solo movida.
MATH_PLUGIN.checkers['eq-linear'] = function(ex, ctx){
  return state.eqlDone === true;
};

// Prompt 17 (2026-09-08, experimento controlado de despacho mínimo entre
// dominios): lista mínima de objetos de dominio que el despacho de
// renderExercise()/handleConfirm() consulta para resolver quién es dueño
// de un kind — reemplaza el nombre literal "MATH_PLUGIN" hardcodeado en
// esos 2 puntos (Prompt 10/14) por una búsqueda sobre esta lista. NO es un
// registry formal: sin API de discovery/registro, sin factory, sin clase
// base — un array plano, mutable, que un experimento externo (fixture) puede
// extender en runtime (`DOMAIN_PLUGINS.push(...)`) sin tocar este archivo.
// Con un único elemento (MATH_PLUGIN), el comportamiento para todo
// contenido real existente es idéntico al de antes — mismo resultado,
// mismo orden, cero cambio observable. Contrato que cada elemento debe
// cumplir: `especificaciones/.../contrato-minimo-dominio` (Prompt 16) —
// obligatorio `renderers`/`checkers`/`checkCorrect`, los otros 6 hooks
// (`validateExtra`/`resetState`/`showsSupport`/`onReveal`/
// `markFinalCorrect`/`getHadError`) siguen consultándose SOLO en
// MATH_PLUGIN, sin generalizar — Prompt 17 confirmó que no hacía falta
// (ver informe, Experimento D).
const DOMAIN_PLUGINS = [MATH_PLUGIN];

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════
   MUNDO — kind del Motor Base (2026-10-19, decisión del Director: transversal a todas las materias; contrato: especificaciones/contratos/CONTRATO_MUNDO_v1.md)
   «El mundo responde»: el alumno arma una jugada (qué pieza va en cada hueco) y la ejecuta sobre un MUNDO (una ficha, una agenda, un diálogo…): la consecuencia se ve en un tablero.
   El corredor (MundoRunner) es una función pura que decide el veredicto a partir de lo que PASÓ, no de una clave; el renderizador lo muestra. Mismas piezas para cualquier materia: el contenido (el mundo) es un JSON de la Unidad.
   Criterio de diseño (Director): la regla fija es la CONTINUIDAD ESTÉTICA con el resto de la app y un minimalismo que no pierda lo estético; entrar en una pantalla es una guía, no una regla.
     · Ficha y agenda: escena con la burbuja del personaje, tablero y piezas. Diálogo: una conversación que CRECE hacia abajo, con el tablero fijo arriba.
     · Práctica: el efecto de cada pieza se ve en el tablero MIENTRAS se elige (consecuencia, no veredicto); «Probalo» EJECUTA (escribe letra por letra) y marca el veredicto.
     · Skill Check: SIN vista previa y sin reacciones; «Probalo» escribe todo y marca todo junto al final (un solo intento, sin ayuda).
   El corredor de abajo es copia EXACTA de plataforma/studio/mundo/runner.js (lo comprueba la prueba mundo-runner-sincronizado); no se edita acá. */
var MundoRunner = (function () {
  'use strict';

  const pieza = (m, id) => m.piezas.find(p => p.id === id);
  const campo = (m, id) => m.campos.find(c => c.id === id);
  const enObjetivo = (m, id) => Object.prototype.hasOwnProperty.call(m.objetivo, id);

  /** jugada: { huecoId: piezaId }. Devuelve { traza, estado, diferencias, logrado, cuenta }. */
  function correr(m, jugada) {
    const estado = {};                    // campoId -> { valor, huecoId, estado }
    const traza = [];
    for (const h of m.huecos) {
      const pid = jugada[h.id];
      if (!pid) { traza.push({ hueco: h.id, estado: 'vacio' }); continue; }
      const p = pieza(m, pid);
      if (!p) throw new Error('pieza inexistente: ' + pid);
      if (!p.efecto) {
        // Pieza de FORMA (la frase está mal armada: «I live from Chile.»). Si declara `forma:{campo,valor}` CAE EN SU LUGAR como cualquier otra: el mundo escribe lo que entendió (el valor, con la forma tal cual) en esa fila,
        // que queda en ámbar al probar. Así NINGUNA pieza delata el error por no tener dónde ponerse (hallazgo del Director, 2026-10-19). Sin `forma`, no cae en ningún lado (control C14).
        if (p.forma && p.forma.campo) {
          const cid = p.forma.campo, valor = p.forma.valor;
          if (!campo(m, cid)) throw new Error('la forma de ' + pid + ' apunta a un campo que no existe: ' + cid);
          if (estado[cid]) { const antes = traza.find(t => t.campo === cid && !t.reemplazado); if (antes) antes.reemplazado = true; }
          estado[cid] = { valor, hueco: h.id, estado: !enObjetivo(m, cid) ? 'sobra' : 'distinto', forma: true };
          traza.push({ hueco: h.id, pieza: pid, texto: p.texto, campo: cid, valor, estado: 'no-entendio', forma: true, reaccion: p.reaccion || null });
        } else traza.push({ hueco: h.id, pieza: pid, texto: p.texto, estado: 'no-entendio', reaccion: p.reaccion || null });
        continue;
      }
      const ids = Object.keys(p.efecto);
      ids.forEach((cid, k) => {
        const valor = p.efecto[cid];
        if (!campo(m, cid)) throw new Error('el efecto de ' + pid + ' apunta a un campo que no existe: ' + cid);
        const est = !enObjetivo(m, cid) ? 'sobra' : (valor === m.objetivo[cid] ? 'ok' : 'distinto');
        if (estado[cid]) { const antes = traza.find(t => t.campo === cid && !t.reemplazado); if (antes) antes.reemplazado = true; }
        estado[cid] = { valor, hueco: h.id, estado: est };
        traza.push({ hueco: h.id, pieza: pid, texto: k === 0 ? p.texto : undefined, campo: cid, valor, estado: est, reaccion: p.reaccion || null });
      });
    }
    const diferencias = { faltan: [], distinto: [], sobran: [], noEntendio: [] };
    for (const cid of Object.keys(m.objetivo)) {
      if (!estado[cid]) diferencias.faltan.push(cid);
      else if (estado[cid].valor !== m.objetivo[cid]) diferencias.distinto.push(cid);
    }
    for (const cid of Object.keys(estado)) if (!enObjetivo(m, cid)) diferencias.sobran.push(cid);
    for (const t of traza) if (t.estado === 'no-entendio') diferencias.noEntendio.push(t.hueco);
    const cuenta = { ok: Object.keys(m.objetivo).length - diferencias.faltan.length - diferencias.distinto.length, total: Object.keys(m.objetivo).length };
    const incompleta = m.huecos.some(h => !jugada[h.id]);
    const logrado = !incompleta && !diferencias.faltan.length && !diferencias.distinto.length && !diferencias.sobran.length && !diferencias.noEntendio.length;
    return { traza, estado, diferencias, logrado, cuenta, incompleta };
  }

  const plural = (n, par) => n === 1 ? par[0] : par[1];

  /** Consecuencia en palabras. NUNCA nombra el valor correcto: dice QUÉ pasó y DÓNDE mirar (Correction Contract: señala el proceso). */
  function mensaje(m, r) {
    const v = Object.assign({ dato: ['dato', 'datos'], referencia: 'el carnet', receptor: 'Leo', pieza: ['frase', 'frases'], sobra: ['cosa de más', 'cosas de más'], falta: ['dato', 'datos'] }, m.vocab || {});
    if (r.logrado) return { ok: true, titulo: (m.textos && m.textos.okTitulo) || '¡Quedó igual!', texto: (m.textos && m.textos.okTexto) || 'Todo coincide.' };
    const d = r.diferencias, partes = [];
    if (r.cuenta.total) partes.push(r.cuenta.ok + ' de ' + r.cuenta.total + ' ' + v.dato[1] + ' coinciden con ' + v.referencia + '.');
    if (d.noEntendio.length) partes.push(v.receptor + ' no entendió ' + d.noEntendio.length + ' ' + plural(d.noEntendio.length, v.pieza) + '.');
    if (d.sobran.length) partes.push('Hay ' + d.sobran.length + ' ' + plural(d.sobran.length, v.sobra) + '.');
    if (d.faltan.length && !d.noEntendio.length) partes.push(plural(d.faltan.length, ['Falta ', 'Faltan ']) + d.faltan.length + ' ' + plural(d.faltan.length, v.falta) + '.');
    return { ok: false, titulo: (m.textos && m.textos.casiTitulo) || 'Casi.', texto: partes.join(' ') + ' Mirá las filas marcadas.' };
  }

  /** Todas las jugadas posibles (banco común sin repetir piezas; con `opciones`, una por hueco). Generador. */
  function* jugadas(m) {
    const hs = m.huecos;
    const comun = hs.every(h => !h.opciones);
    if (!comun) {
      const rec = function* (i, acc) {
        if (i === hs.length) { yield Object.assign({}, acc); return; }
        for (const pid of (hs[i].opciones || m.piezas.map(p => p.id))) { acc[hs[i].id] = pid; yield* rec(i + 1, acc); }
      };
      yield* rec(0, {}); return;
    }
    const ids = m.piezas.map(p => p.id), usados = new Set();
    const rec = function* (i, acc) {
      if (i === hs.length) { yield Object.assign({}, acc); return; }
      for (const pid of ids) { if (usados.has(pid)) continue; usados.add(pid); acc[hs[i].id] = pid; yield* rec(i + 1, acc); usados.delete(pid); }
    };
    yield* rec(0, {});
  }

  /** Todas las jugadas que logran el mundo (límite para no colgar). */
  function soluciones(m, limite) {
    const out = []; let n = 0;
    for (const j of jugadas(m)) { n++; if (correr(m, j).logrado) { out.push(j); if (limite && out.length >= limite) break; } }
    return { soluciones: out, evaluadas: n };
  }
  /** Una solución (para que el arnés de QA y el botón «ver cómo se arma» puedan jugar el mundo). null si no tiene. */
  function resolver(m) { const s = soluciones(m, 1).soluciones; return s.length ? s[0] : null; }

  /** Orden de las piezas del banco para MOSTRAR. Estable (misma mezcla cada vez que se abre el mundo, así las pastillas no saltan) pero sin relación con cuál es
   *  la correcta. Hallazgo real del Director (2026-10-19, prueba en teléfono, nota «las opciones son siempre las primeras»): el orden de autoría ponía las
   *  correctas adelante y el Skill Check se resolvía tocando las primeras. Medida: P(una correcta sale antes que un distractor) (el AUC); 0,5 = sin relación,
   *  1 = las correctas siempre primero. Se busca la primera mezcla con P entre 0,35 y 0,65. */
  function sesgoBanco(m, orden) {
    const sol = resolver(m); const c = new Set(sol ? Object.values(sol) : []); const o = orden || m.piezas.map(p => p.id);
    const pos = o.map((id, i) => c.has(id) ? i : -1).filter(i => i >= 0), neg = o.map((id, i) => c.has(id) ? -1 : i).filter(i => i >= 0);
    if (!pos.length || !neg.length) return 0.5;
    let antes = 0; for (const a of pos) for (const b of neg) if (a < b) antes++;
    return antes / (pos.length * neg.length);
  }
  function bancoCumple(m, orden) { const s = sesgoBanco(m, orden || ordenBanco(m)); return s >= 0.35 && s <= 0.65; }
  function ordenBanco(m) {
    const ids = m.piezas.map(p => p.id);
    const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
    const prng = (a) => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
    let mejor = ids.slice(), mejorD = 9;
    for (let salt = 0; salt < 500; salt++) {
      const r = prng(hash(String(m.id) + '|' + salt)), o = ids.slice();
      for (let i = o.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [o[i], o[j]] = [o[j], o[i]]; }
      const s = sesgoBanco(m, o), d = Math.abs(s - 0.5);
      if (s >= 0.35 && s <= 0.65) return o;
      if (d < mejorD) { mejorD = d; mejor = o; }
    }
    return mejor;
  }

  return { correr, mensaje, jugadas, soluciones, resolver, pieza, campo, ordenBanco, bancoCumple, sesgoBanco };
})();
