    state.mundoLogrado = false;
    var esc_ = def.escena, wrap = el('div', 'mundo-wrap' + (/noche/.test(esc_.fondoPantalla || '') ? ' tema-noche' : '')), sc = ex.role === 'skill_check';
    try { [['pildoraCremaImg', '--pdp-pildora-crema'], ['opcionAzulImg', '--pdp-opcion-azul'], ['opcionDoradaImg', '--pdp-opcion-dorada'], ['circuloAzulImg', '--pdp-circulo-azul'], ['circuloDoradoImg', '--pdp-circulo-dorado'], ['etiquetaNombreImg', '--pdp-nombre'], ['retratoMarcoImg', '--pdp-retrato-marco'], ['globoPuntaImg', '--pdp-globo-punta']].forEach(function (p_) { if (esc_[p_[0]]) document.documentElement.style.setProperty(p_[1], 'url(' + esc_[p_[0]] + ')'); }); } catch (_) {}   // piezas del Director: marco del globo (crema), opciones (azul = sin elegir, dorada = elegida) con su círculo de letra, y la etiqueta del nombre
