    if (def.tipo === 'analizador' && typeof APP_CONFIG !== 'undefined' && APP_CONFIG.fondoEjercicios) { try { pdpMarcoGlobo(wrap.querySelector('.mundo-dice'), { k: 0.14, emax: 40, cola: 15, cy: 28, ancho: 10 }); } catch (_) {} }   // solo el globo de Maya en el analizador lleva el recuadro del cartel, con las cinco capas finas (pedido del Director)
    dice(M, '', def.consigna.banner);
