  // Ganchos del Motor (renderExercise / setExerciseState): no hacen nada fuera del rol alumno
  function alMostrarEjercicio(ex){
    try{ document.body.classList.toggle('sy-lc', esLevelCheckClase()); }catch(_){} // Level Check en clase: sin "Saltar"
    if(unoTel()){ uno.marcas={}; uno.ayuda={}; cerrarHojaUno(); prepararUno(); ui.unoPill.hidden=(ex.kind==='profe' && ex.forma!=='pasale'); return; } // un solo teléfono: en un momento con el profe la hoja se abre desde el botón principal
    if(rol!=='alumno') return;
    const exs=getActiveExercises(state.currentModule);
    ejAlumno={ id:String(ex.id), idx:state.currentExerciseIndex+1, total:exs.length, kind:ex.kind }; estAlumno='INICIAL'; esperaFn=null; puede=false; pagAlumno=null;
    informarEjercicio(); informarResp();
  }
  function alCambiarEstado(next){ if(rol!=='alumno') return; estAlumno=next; informarEstado(); }

  /* ── Lado adulto ── */
  function respuestaCorrecta(ex){
    if(!ex) return '';
    const op=i=>Array.isArray(ex.options)?String(ex.options[i]):String(i);
    switch(ex.kind){
      case 'mc': return op(ex.correct);
      case 'tf': return ex.correct===true?'Verdadero':'Falso';
      case 'mc-multi': return (Array.isArray(ex.correct)?ex.correct:[]).map(op).join(' · ');
      case 'word-bank': return (ex.answers&&ex.answers.length)?ex.answers.join(' / '):String((ex.bank||[])[ex.correct]||'');
      case 'order': return (ex.correctOrder||ex.correct||[]).map(i=>ex.words[i]).join(' ');
      case 'fill': return String(ex.answer||'')+((ex.acceptVariants&&ex.acceptVariants.length)?'   (también vale: '+ex.acceptVariants.slice(0,3).join(' · ')+(ex.acceptVariants.length>3?' …':'')+')':'');
      case 'error-find': return '"'+String((ex.sentence||[])[ex.errorIndex]||'')+'" → "'+String(ex.correction||'')+'"';
      case 'free': return 'Respuesta libre: la evalúa el adulto.';
      // tipos de reconocimiento y asociación (2026-10-07, L2 de EN-A2-U01): el profesor también ve la respuesta
      case 'listen': return (typeof ex.correct==='number' && Array.isArray(ex.options)) ? op(ex.correct) : '';
      case 'match': { const L=ex.left||[], R=ex.right||[], P=ex.pairs||{}; return L.map((t,i)=>t+' → '+(R[P[i]]!=null?R[P[i]]:'?')).join(' · '); }
      case 'classify': { const it=ex.items||[], ca=ex.categories||[], co=ex.correct||[]; return ca.map((c,k)=>c+': '+it.filter((_,i)=>co[i]===k).join(', ')).join(' · '); }
      case 'timeline': return (ex.correctOrder||[]).map(i=>(ex.events||[])[i]).join(' → ');
      case 'table-fill': return (ex.answers||[]).join(' · ');
      case 'memory': return (ex.pairs||[]).map(p=>p.a+' = '+p.b).join(' · ');
      case 'label-diagram': return (ex.zones||[]).map((z,i)=>(i+1)+': '+z.label).join(' · ');
      default: return '';
    }
  }
  function respuestaDelAlumno(ex, r){
    if(!ex||r==null||r==='') return '';
    const op=i=>Array.isArray(ex.options)?String(ex.options[i]):String(i);
    switch(ex.kind){
      case 'mc': return (r===null)?'':op(r);
      case 'tf': return r===true?'Verdadero':(r===false?'Falso':'');
      case 'mc-multi': return (Array.isArray(r)?r:[]).map(op).join(' · ');
      case 'word-bank': return String(r).replace(/_+/g,'').trim();
      case 'order': return (Array.isArray(r)?r:[]).map(i=>ex.words[i]).join(' ');
      case 'fill': case 'free': return String(r);
      case 'listen': return (typeof r==='number') ? op(r) : '';
      case 'match': { const L=ex.left||[], R=ex.right||[]; const ks=Object.keys(r||{}); return ks.length ? ks.map(k=>L[k]+' → '+R[r[k]]).join(' · ') : ''; }
      case 'classify': { const it=ex.items||[], ca=ex.categories||[]; const ks=Object.keys(r||{}); return ks.length ? ks.map(k=>it[k]+' → '+ca[r[k]]).join(' · ') : ''; }
      case 'error-find': return (r&&r.selected!=null&&ex.sentence?'marcó "'+ex.sentence[r.selected]+'"':'')+(r&&r.correction?'  ·  escribió "'+r.correction+'"':'');
      default: return '';
    }
  }
