    ui.adMarcasW=el('div','ad-marcasw'); ui.adDock.appendChild(ui.adMarcasW);
    ui.adAvanzar=el('button','pds-btn-depth ad-av','Avanzar al alumno'); ui.adAvanzar.type='button'; ui.adAvanzar.onclick=()=>{ ui.aviso=null; enviar({t:'avanzar'}); pintarAdulto(); }; ui.adDock.appendChild(ui.adAvanzar);
    ui.adAviso=el('p','ad-aviso',''); ui.adDock.appendChild(ui.adAviso);
