      r.total=Math.max(r.total,1); r.correctos=Math.max(0,r.total-3);
      r.scDet=r.scDet.map((d,i)=>i===0?{ ok:false, que:d.que, porque:d.porque||'Mirá con calma lo que dice el ejemplo: es el dato que cambia.' }:{ ok:true, que:d.que, porque:'' }); r.sc=r.scDet.map(d=>d.ok);
