    if(img){ const i=document.createElement('img'); i.src=img; i.alt=(TUTOR&&TUTOR.nombre)||'Tu tutor'; hero.appendChild(i); } else hero.appendChild(el('div','sy-fin-ini',(TUTOR&&TUTOR.inicial)||'S'));
