    ov.appendChild(el('p','sy-fin-dice','“'+(soloLectura?'Terminaste la lectura. Seguimos.':mensajeSpike(r))+'”'));
    const tiles=el('div','sy-fin-tiles');
    if(!soloLectura){ const t1=el('div','sy-fin-tile'); t1.appendChild(el('div','sy-fin-v',r.correctos+' de '+r.total)); t1.appendChild(el('div','sy-fin-l','Correctos')); tiles.appendChild(t1); }
    if(r.sc.length){ const t2=el('div','sy-fin-tile'); const pts=el('div','sy-fin-pts'); r.sc.forEach(ok=>pts.appendChild(el('span','sy-fin-pt'+(ok?' ok':'')))); t2.appendChild(pts); t2.appendChild(el('div','sy-fin-l','Skill Check')); tiles.appendChild(t2); }
    const IC_LIBRO='<svg class="sy-fin-ic" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 6.5C10.5 5 8 4.5 4 4.5v13c4 0 6.5.5 8 2 1.5-1.5 4-2 8-2v-13c-4 0-6.5.5-8 2zM12 6.5v13"/></svg>', IC_CINTA='<svg class="sy-fin-ic" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="9" r="5.2"/><circle cx="12" cy="9" r="2.4"/><path d="M8.6 13.4L7 21l5-2.6 5 2.6-1.6-7.6"/></svg>';
    [...tiles.children].forEach((tl,k)=>{ const ic=document.createElement('span'); ic.className='sy-fin-icw'; ic.innerHTML=k===0?IC_LIBRO:IC_CINTA; tl.insertBefore(ic,tl.firstChild); ['tl','tr','bl','br'].forEach(q=>{ const f=el('i','pc-esq pc-esq-'+q); f.setAttribute('aria-hidden','true'); tl.appendChild(f); }); });   // ícono + esquinas ornamentales (CSS puro)
    if(tiles.children.length) ov.appendChild(tiles);
