      const sec=el('div','sy-fin-sec sy-fin-sc'); sec.appendChild(el('div','sy-lbl','Tu Skill Check'));
      r.scDet.forEach(d=>{ const f=el('div','sy-fin-scf'+(d.ok?' ok':' no')); f.appendChild(el('span','sy-fin-sci',d.ok?'✓':'!')); const tx=el('div','sy-fin-sct'); tx.appendChild(el('div','sy-fin-scq',d.que)); if(d.porque) tx.appendChild(el('div','sy-fin-scp','Por qué: '+d.porque)); f.appendChild(tx); sec.appendChild(f); });
