    if(r.pend.length){ const sec=el('div','sy-fin-sec'); sec.appendChild(el('div','sy-lbl','Para retomar con tu profe')); const ch=el('div','sy-fin-chips'); r.pend.forEach(t=>ch.appendChild(el('div','sy-fin-chip rep','↻ '+t))); sec.appendChild(ch); ov.appendChild(sec); }
    const ok=el('button','pds-btn-depth','Seguir'); ok.type='button'; { const fl=el('span','sy-fin-fl',' →'); fl.setAttribute('aria-hidden','true'); ok.appendChild(fl); }
    ok.onclick=()=>{ quitar(ui.finAl); ui.finAl=null; if(demo) return; state.pmapRestoreNivel=nivelId; state.currentNivel=null; goToScreen('screen-dot-nav'); };
    ov.appendChild(ok); document.body.appendChild(ov);
