    if(!demo && rol==='alumno' && conectado) enviar({ t:'fin', nombre:(n&&n.nombre)||'', total:r.total, correctos:r.correctos, sc:r.sc, repasar:r.temas.filter(t=>t.repasar).map(t=>t.tema).concat(r.pend) });
